type FuelRecord = { id?:number; vehicleId?:number; occurredAt:string; odometer:number; station:string; fuelType:string; gallons:number; pricePerGallon:number; total:number; payment:string; fillType:string; notes:string };
type MaintenanceRecord = { id?:number; vehicleId?:number; occurredAt:string; odometer:number; movementType:string; category:string; issue:string; workDone:string; shop:string; phone:string; laborCost:number; partsCost:number; total:number; warranty:string; nextKm:number|null; notes:string };
type WorkSessionRecord = { id:number; vehicleId?:number; role:"independiente"|"plataforma"; platforms:string; activity:string; startedAt:string; endedAt:string|null; startOdometer:number; endOdometer:number|null; income:number; expenses:number };
type TripRecord = { id?:number; vehicleId?:number; startedAt:string; endedAt:string; durationSeconds:number; distanceKm:number; startLat:number|null; startLng:number|null; endLat:number|null; endLng:number|null; routePoints?:TrackPoint[]|null; maxSpeedKmh?:number|null; avgSpeedKmh?:number|null };
type DashboardSummary = { fuel:{spent:number;gallons:number;fills:number}; maintenance:{spent:number;entries:number;next_km:number|null}; sessions:{income:number;expenses:number;net:number;hours:number;km:number;sessions:number}; trips:{km:number;count:number;seconds:number}; cost_per_km:number|null; real_net:number };
type ServiceQuoteRecord = { id?:number; vehicleId?:number; serviceName:string; createdAt:string; startOdometer:number; endOdometer:number; serviceKm:number; extraKm:number; totalKm:number; fuelPrice:number; efficiencyKpg:number; fuelCost:number; wearPerKm:number; wearCost:number; tolls:number; otherCosts:number; hours:number; hourlyRate:number; timeCost:number; commissionPct:number; marginPct:number; operatingCost:number; recommendedPrice:number; pricePerKm:number };
type VehicleDocumentRecord = { id?:number; vehicleId?:number; documentType:string; documentNumber:string; issuedAt:string; expiresAt:string; provider:string; notes:string; createdAt?:string };
const money = new Intl.NumberFormat("es-CO", { style: "currency", currency: "COP", maximumFractionDigits: 0 });
const localDateInput=()=>{const d=new Date(),offset=d.getTimezoneOffset();return new Date(d.getTime()-offset*60000).toISOString().slice(0,10)};
const localDateTimeInput=()=>{const d=new Date(),offset=d.getTimezoneOffset();return new Date(d.getTime()-offset*60000).toISOString().slice(0,16)};
const formatDuration=(seconds:number)=>`${String(Math.floor(seconds/3600)).padStart(2,"0")}:${String(Math.floor(seconds%3600/60)).padStart(2,"0")}:${String(seconds%60).padStart(2,"0")}`;
const haversineKm=(a:{lat:number;lng:number},b:{lat:number;lng:number})=>{const radius=6371,toRad=(value:number)=>value*Math.PI/180,dLat=toRad(b.lat-a.lat),dLng=toRad(b.lng-a.lng),x=Math.sin(dLat/2)**2+Math.cos(toRad(a.lat))*Math.cos(toRad(b.lat))*Math.sin(dLng/2)**2;return 2*radius*Math.asin(Math.sqrt(x))};
