function LoginFlow({authenticated}:{authenticated:()=>void}) {
  const [mode,setMode]=useState<"login"|"signup">("login"); const [email,setEmail]=useState(""); const [password,setPassword]=useState("");
  const [busy,setBusy]=useState(false); const [error,setError]=useState(""); const [message,setMessage]=useState("");
  const submit=async(event:React.FormEvent)=>{event.preventDefault();if(busy)return;setBusy(true);setError("");setMessage("");
    try{const supabase=getSupabaseBrowserClient();
      if(mode==="login"){const {error:authError}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(authError)throw authError;authenticated()}
      else{const {data,error:authError}=await supabase.auth.signUp({email:email.trim(),password,options:{emailRedirectTo:window.location.origin}});if(authError)throw authError;if(data.session)authenticated();else setMessage("Revisa tu correo y confirma la cuenta para entrar a Autoram.")}
    }catch(reason){setError(reason instanceof Error?reason.message:"No pudimos completar el ingreso.")}finally{setBusy(false)}};
  return <main className="login-page"><section className="login-brand-panel"><div className="login-logo"><Brand/></div><div className="login-message"><span>AUTORAM COLOMBIA</span><h1>Tu vehículo.<br/><em>Tus números.</em><br/>Tu camino.</h1><p>Combustible, recorridos, mantenimiento y rentabilidad en una experiencia diseñada para conductores colombianos.</p></div><div className="login-proof"><div><ShieldCheck size={18}/><span><b>Información protegida</b><small>Cada conductor ve únicamente sus datos</small></span></div><div><Disc3 size={18}/><span><b>Parque automotor</b><small>Varios vehículos en una sola cuenta</small></span></div></div></section><section className="login-form-panel"><div className="login-mobile-brand"><Brand/></div><div className="login-box"><div className="code-icon"><ShieldCheck size={26}/></div><small className="login-over">{mode==="login"?"ACCESO SEGURO":"NUEVA CUENTA"}</small><h2>{mode==="login"?"Bienvenido a Autoram":"Crea tu cuenta"}</h2><p>{mode==="login"?"Ingresa con el correo y la contraseña que registraste.":"Tu información quedará sincronizada y protegida en todos tus dispositivos."}</p>{error&&<div className="form-error"><AlertTriangle size={16}/>{error}</div>}{message&&<div className="auth-success"><Check size={16}/>{message}</div>}<form className="auth-form" onSubmit={submit}><label><span>Correo electrónico</span><input type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="nombre@correo.com" required/></label><label><span>Contraseña</span><input type="password" autoComplete={mode==="login"?"current-password":"new-password"} minLength={8} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Mínimo 8 caracteres" required/></label><button className="login-main" type="submit" disabled={busy}>{busy?"Conectando…":mode==="login"?"Ingresar":"Crear cuenta"}<ChevronRight size={18}/></button></form><button className="auth-toggle" type="button" onClick={()=>{setMode(mode==="login"?"signup":"login");setError("");setMessage("")}}>{mode==="login"?"¿Primera vez? Crear una cuenta":"Ya tengo cuenta · Ingresar"}</button><div className="security-note"><LockKeyhole size={17}/><span>Autenticación y registros protegidos por Supabase.</span></div><p className="terms">Al continuar aceptas los términos de uso y la política de privacidad de Autoram.</p></div></section></main>
}

function DriverOnboarding({complete}:{complete:(driver:DriverProfile)=>Promise<void>}) {
  const [driver,setDriver]=useState<DriverProfile>({fullName:"",document:"",phone:"",email:"",city:"",address:"",license:"",category:"B1"});
  const [saving,setSaving]=useState(false);const [error,setError]=useState("");
  const update=(key:keyof DriverProfile,value:string)=>setDriver(v=>({...v,[key]:value}));
  const ready=Boolean(driver.fullName.trim()&&driver.document.trim()&&driver.phone.replace(/\D/g,"").length>=10&&driver.city.trim()&&driver.license.trim());
  return <main className="onboarding-page"><header className="onboarding-top"><Brand/><span>PERFIL DEL CONDUCTOR</span><small>TUS DATOS · TU CONTROL</small></header><div className="onboarding-layout driver-layout"><aside className="onboarding-intro"><small>ANTES DEL VEHÍCULO</small><h1>Primero,<br/><em>conozcámonos.</em></h1><p>Estos datos identifican al conductor y permiten personalizar documentos, alertas y jornadas dentro de Autoram.</p><div className="driver-benefits"><span><UserRound size={18}/><b>Datos personales</b><small>Información básica de contacto</small></span><span><FileCheck2 size={18}/><b>Licencia de conducción</b><small>Número y categoría vigente</small></span><span><MapPin size={18}/><b>Ubicación principal</b><small>Ciudad y dirección de residencia</small></span></div></aside><section className="onboarding-card driver-card"><div className="onboarding-progress"><span>PASO PREVIO</span><i><em style={{width:"100%"}}/></i><b>PERFIL</b></div><div className="onboarding-panel"><div className="onboarding-heading"><span><UserRound size={24}/></span><div><small>DATOS DEL CONDUCTOR</small><h2>Crea tu perfil</h2><p>Luego registraremos los datos técnicos de tu vehículo.</p></div></div>{error&&<div className="form-error"><AlertTriangle size={16}/>{error}</div>}<form className="onboarding-fields driver-fields" onSubmit={async e=>{e.preventDefault();if(!ready||saving)return;setSaving(true);setError("");try{await complete(driver)}catch(err){setError(err instanceof Error?err.message:"No pudimos guardar el perfil");setSaving(false)}}}><Field label="Nombre completo" required wide><input value={driver.fullName} onChange={e=>update("fullName",e.target.value)} placeholder="Ej. Carlos Gómez" autoFocus/></Field><Field label="Número de cédula" required><input value={driver.document} onChange={e=>update("document",e.target.value.replace(/\D/g,"").slice(0,12))} inputMode="numeric" placeholder="Ej. 1234567890"/></Field><Field label="Celular" required><input value={driver.phone} onChange={e=>update("phone",e.target.value.slice(0,15))} inputMode="tel" placeholder="Ej. 300 123 4567"/></Field><Field label="Correo electrónico"><input value={driver.email} onChange={e=>update("email",e.target.value)} type="email" placeholder="nombre@correo.com"/></Field><Field label="Ciudad o municipio" required><input value={driver.city} onChange={e=>update("city",e.target.value)} placeholder="Ej. Villavicencio"/></Field><Field label="Dirección de residencia" wide><input value={driver.address} onChange={e=>update("address",e.target.value)} placeholder="Barrio, calle, carrera o conjunto"/></Field><Field label="Número de licencia" required><input value={driver.license} onChange={e=>update("license",e.target.value.replace(/\D/g,"").slice(0,15))} inputMode="numeric" placeholder="Número de licencia"/></Field><Field label="Categoría"><select value={driver.category} onChange={e=>update("category",e.target.value)}><option>A1</option><option>A2</option><option>B1</option><option>B2</option><option>B3</option><option>C1</option><option>C2</option><option>C3</option></select></Field><button className="primary driver-continue" type="submit" disabled={!ready||saving}>{saving?"Guardando…":"Continuar al vehículo"}<ChevronRight size={17}/></button></form></div></section></div></main>
}

function VehicleOnboarding({complete}:{complete:(vehicle:VehicleProfile)=>void}) {
  const [step,setStep]=useState(1);
  const [vehicle,setVehicle]=useState<VehicleProfile>({type:"Carro",brand:"",model:"",version:"",year:"2024",plate:"",color:"",fuel:"Gasolina corriente",transmission:"Automática",odometer:"",tires:"Bueno",brakes:"Bueno",fluids:"Bueno",battery:"Bueno",general:"Bueno",vin:"",imageUrl:"",imageAttribution:""});
  const [vinState,setVinState]=useState<"idle"|"loading"|"found"|"error">("idle");
  const [photoState,setPhotoState]=useState<"idle"|"loading"|"found"|"error">("idle");
  const update=(key:keyof VehicleProfile,value:string)=>setVehicle(v=>({...v,[key]:value}));
  const findVehicleImage=async(make=vehicle.brand,model=vehicle.model,year=vehicle.year)=>{if(!make||!model)return;setPhotoState("loading");try{const query=encodeURIComponent(`${make} ${model} ${year}`);const response=await fetch(`https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch=${query}&gsrnamespace=6&gsrlimit=6&prop=imageinfo&iiprop=url%7Cextmetadata&iiurlwidth=900&format=json&origin=*`);if(!response.ok)throw new Error("image");const data=await response.json();const pages=Object.values(data.query?.pages||{}) as Array<{imageinfo?:Array<{thumburl?:string;url?:string;descriptionurl?:string;extmetadata?:Record<string,{value?:string}>}>}>;const info=pages.map(p=>p.imageinfo?.[0]).find(Boolean);if(!info?.thumburl&&!info?.url)throw new Error("image");const author=String(info.extmetadata?.Artist?.value||"Wikimedia Commons").replace(/<[^>]*>/g,"").slice(0,90);setVehicle(v=>({...v,imageUrl:info.thumburl||info.url||"",imageAttribution:`${author} · Wikimedia Commons`}));setPhotoState("found")}catch{setPhotoState("error")}};
  const lookupVin=async()=>{const vin=vehicle.vin.trim().toUpperCase();if(vin.length<8){setVinState("error");return}setVinState("loading");try{const response=await fetch(`https://vpic.nhtsa.dot.gov/api/vehicles/DecodeVinValuesExtended/${encodeURIComponent(vin)}?format=json`);if(!response.ok)throw new Error("vin");const data=await response.json();const found=data.Results?.[0];if(!found?.Make||!found?.Model)throw new Error("vin");const brand=String(found.Make),model=String(found.Model),year=String(found.ModelYear||vehicle.year),fuel=String(found.FuelTypePrimary||vehicle.fuel),transmission=String(found.TransmissionStyle||vehicle.transmission);setVehicle(v=>({...v,vin,brand,model,year,fuel,transmission}));setVinState("found");void findVehicleImage(brand,model,year)}catch{setVinState("error")}};
  const basicsReady=Boolean(vehicle.brand.trim()&&vehicle.model.trim()&&vehicle.year&&vehicle.plate.trim());
  const operationReady=vehicle.odometer!=="";
  const health=[{key:"tires",label:"Estado de las llantas",icon:Disc3},{key:"brakes",label:"Frenos",icon:ShieldCheck},{key:"fluids",label:"Aceite y fluidos",icon:Droplets},{key:"battery",label:"Batería",icon:Activity},{key:"general",label:"Estado general",icon:CarFront}] as const;
  return <main className="onboarding-page"><header className="onboarding-top"><Brand/><span>CONFIGURACIÓN INICIAL</span><small>TU VEHÍCULO · TUS DATOS</small></header><div className="onboarding-layout"><aside className="onboarding-intro"><small>PRIMERA PUESTA A PUNTO</small><h1>Conozcamos<br/>tu <em>vehículo.</em></h1><p>Con estos datos Autoram podrá calcular consumos, anticipar mantenimientos y darte números realmente útiles.</p><div className="onboarding-steps">{[{n:1,t:"Identificación",d:"Tipo, marca y modelo"},{n:2,t:"Datos de operación",d:"Combustible y kilometraje"},{n:3,t:"Estado inicial",d:"Revisión rápida general"}].map(s=><button key={s.n} className={`${step===s.n?"active":""} ${step>s.n?"done":""}`} onClick={()=>step>s.n&&setStep(s.n)}><span>{step>s.n?<Check size={15}/>:s.n}</span><div><b>{s.t}</b><small>{s.d}</small></div></button>)}</div></aside><section className="onboarding-card"><div className="onboarding-progress"><span>PASO {step} DE 3</span><i><em style={{width:`${step/3*100}%`}}/></i><b>{Math.round(step/3*100)}%</b></div>{step===1&&<div className="onboarding-panel"><div className="onboarding-heading"><span><CarFront size={24}/></span><div><small>IDENTIFICACIÓN</small><h2>¿Cuál es tu vehículo?</h2><p>Comienza con la información básica. Podrás editarla después.</p></div></div><div className="vehicle-type-grid">{["Carro","Moto","Camioneta","Taxi","Camión"].map(type=><button type="button" key={type} className={vehicle.type===type?"selected":""} onClick={()=>update("type",type)}><CarFront size={21}/><b>{type}</b>{vehicle.type===type&&<Check size={15}/>}</button>)}</div><div className="onboarding-fields"><Field label="Marca" required><input value={vehicle.brand} onChange={e=>update("brand",e.target.value)} placeholder="Ej. Renault" autoFocus/></Field><Field label="Modelo" required><input value={vehicle.model} onChange={e=>update("model",e.target.value)} placeholder="Ej. Duster"/></Field><Field label="Año" required><select value={vehicle.year} onChange={e=>update("year",e.target.value)}>{Array.from({length:27},(_,i)=>String(2026-i)).map(y=><option key={y}>{y}</option>)}</select></Field><Field label="Placa" required><input value={vehicle.plate} onChange={e=>update("plate",e.target.value.toUpperCase().slice(0,7))} placeholder="ABC 123"/></Field></div><label className="vehicle-photo"><Camera size={21}/><span><b>Agregar foto del vehículo</b><small>Opcional · podrás cambiarla cuando quieras</small></span><input type="file" accept="image/*"/></label></div>}{step===2&&<div className="onboarding-panel"><div className="onboarding-heading"><span><Gauge size={24}/></span><div><small>DATOS DE OPERACIÓN</small><h2>La información que mueve tus números</h2><p>El kilometraje será el punto de partida para tus alertas y servicios.</p></div></div><div className="onboarding-fields"><Field label="Tipo de combustible" required><select value={vehicle.fuel} onChange={e=>update("fuel",e.target.value)}><option>Gasolina corriente</option><option>Gasolina extra</option><option>ACPM / Diésel</option><option>Gas natural</option><option>Eléctrico</option><option>Híbrido</option></select></Field><Field label="Transmisión" required><select value={vehicle.transmission} onChange={e=>update("transmission",e.target.value)}><option>Automática</option><option>Manual</option><option>CVT</option><option>No aplica</option></select></Field><Field label="Kilometraje actual" required wide><div className="odometer-onboarding"><Gauge size={20}/><input type="number" min="0" value={vehicle.odometer} onChange={e=>update("odometer",e.target.value)} placeholder="35.782" autoFocus/><span>km</span></div></Field></div><div className="onboarding-tip"><TimerReset size={19}/><div><b>Este dato es clave</b><small>Con el kilometraje activaremos recordatorios de aceite, llantas, frenos y revisiones.</small></div></div></div>}{step===3&&<div className="onboarding-panel"><div className="onboarding-heading"><span><ShieldCheck size={24}/></span><div><small>ESTADO INICIAL</small><h2>Una revisión rápida</h2><p>No es un diagnóstico técnico. Indica cómo percibes hoy cada componente.</p></div></div><div className="health-list">{health.map(item=><div key={item.key}><span><item.icon size={19}/><b>{item.label}</b></span><div>{["Bueno","Por revisar","Urgente"].map(state=><button type="button" key={state} className={vehicle[item.key]===state?state==="Urgente"?"selected urgent":"selected":""} onClick={()=>update(item.key,state)}>{vehicle[item.key]===state&&<Check size={13}/>} {state}</button>)}</div></div>)}</div><div className="vehicle-summary"><div><CarFront size={28}/></div><span><small>LISTO PARA CREAR</small><b>{vehicle.brand||"Tu vehículo"} {vehicle.model} · {vehicle.plate||"Sin placa"}</b><em>{vehicle.odometer||"0"} km · Estado general {vehicle.general.toLowerCase()}</em></span></div></div>}<div className="onboarding-actions">{step>1?<button type="button" onClick={()=>setStep(step-1)}><ArrowLeft size={17}/>Atrás</button>:<span/>}<button className="primary" type="button" disabled={(step===1&&!basicsReady)||(step===2&&!operationReady)} onClick={()=>step<3?setStep(step+1):complete(vehicle)}>{step===3?<><Check size={17}/>Crear mi vehículo</>:<>Continuar<ChevronRight size={17}/></>}</button></div></section></div></main>
}

function SmartVehicleOnboarding({complete,cancel}:{complete:(vehicle:VehicleProfile)=>Promise<void>;cancel?:()=>void}) {
  const [step,setStep]=useState(1);
  const [vinState,setVinState]=useState<"idle"|"loading"|"found"|"error">("idle");
  const [photoState,setPhotoState]=useState<"idle"|"loading"|"found"|"error">("idle");
  const [saving,setSaving]=useState(false);const [saveError,setSaveError]=useState("");
  const [vehicle,setVehicle]=useState<VehicleProfile>({type:"Carro",brand:"",model:"",version:"",year:"2024",plate:"",color:"",fuel:"Gasolina corriente",transmission:"Automática",odometer:"",tires:"Bueno",brakes:"Bueno",fluids:"Bueno",battery:"Bueno",general:"Bueno",vin:"",imageUrl:"",imageAttribution:""});
  const update=(key:keyof VehicleProfile,value:string)=>setVehicle(v=>({...v,[key]:value}));
  const referenceImage=referenceVehicleImages[vehicle.type]||referenceVehicleImages.Carro;
  const previewImage=vehicle.imageUrl||referenceImage;
  const uploadImage=async(file?:File)=>{
    if(!file)return;
    setPhotoState("loading");
    try{const form=new FormData();form.append("file",file);const response=await autoramFetch("/api/upload",{method:"POST",body:form});const payload=await response.json();if(!response.ok)throw new Error(payload.error||"No pudimos subir la foto");setVehicle(v=>({...v,imageUrl:payload.url,imageAttribution:"Foto del vehículo"}));setPhotoState("found")}catch{setPhotoState("error")}
  };
  const findImage=async(make=vehicle.brand,model=vehicle.model,year=vehicle.year)=>{
    if(!make||!model)return;setPhotoState("loading");
    try{
      const query=encodeURIComponent(`${make} ${model} ${year}`);
      const response=await fetch(`https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch=${query}&gsrnamespace=6&gsrlimit=6&prop=imageinfo&iiprop=url%7Cextmetadata&iiurlwidth=900&format=json&origin=*`);
      if(!response.ok)throw new Error("image");
      const data=await response.json();
      const pages=Object.values(data.query?.pages||{}) as Array<{imageinfo?:Array<{thumburl?:string;url?:string;extmetadata?:Record<string,{value?:string}>}>}>;
      const info=pages.map(p=>p.imageinfo?.[0]).find(Boolean);
      if(!info?.thumburl&&!info?.url)throw new Error("image");
      const author=String(info.extmetadata?.Artist?.value||"Wikimedia Commons").replace(/<[^>]*>/g,"").slice(0,90);
      setVehicle(v=>({...v,imageUrl:info.thumburl||info.url||"",imageAttribution:`${author} · Wikimedia Commons`}));setPhotoState("found");
    }catch{setPhotoState("error")}
  };
  const lookupVin=async()=>{
    const vin=vehicle.vin.trim().toUpperCase();if(vin.length<8){setVinState("error");return}setVinState("loading");
    try{
      const response=await fetch(`https://vpic.nhtsa.dot.gov/api/vehicles/DecodeVinValuesExtended/${encodeURIComponent(vin)}?format=json`);
      if(!response.ok)throw new Error("vin");const data=await response.json();const found=data.Results?.[0];if(!found?.Make||!found?.Model)throw new Error("vin");
      const brand=String(found.Make),model=String(found.Model),year=String(found.ModelYear||vehicle.year),fuel=String(found.FuelTypePrimary||vehicle.fuel),transmission=String(found.TransmissionStyle||vehicle.transmission);
      setVehicle(v=>({...v,vin,brand,model,year,fuel,transmission}));setVinState("found");void findImage(brand,model,year);
    }catch{setVinState("error")}
  };
  const basicsReady=Boolean(vehicle.brand.trim()&&vehicle.model.trim()&&vehicle.year&&vehicle.plate.trim());
  const health=[{key:"tires",label:"Estado de las llantas",icon:Disc3},{key:"brakes",label:"Frenos",icon:ShieldCheck},{key:"fluids",label:"Aceite y fluidos",icon:Droplets},{key:"battery",label:"Batería",icon:Activity},{key:"general",label:"Estado general",icon:CarFront}] as const;
  return <main className="onboarding-page">
    <header className="onboarding-top"><Brand/><span>CONFIGURACIÓN INTELIGENTE</span>{cancel?<button type="button" onClick={cancel}>Cancelar</button>:<small>VIN · DATOS · ESTADO</small>}</header>
    <div className="onboarding-layout"><aside className="onboarding-intro"><small>PRIMERA PUESTA A PUNTO</small><h1>Tu vehículo,<br/><em>reconocido.</em></h1><p>Ingresa el VIN y Autoram intentará completar los datos y buscar una imagen representativa. Siempre podrás corregirlos.</p><div className="onboarding-steps">{[{n:1,t:"Identificación",d:"VIN, marca y modelo"},{n:2,t:"Datos de operación",d:"Combustible y kilometraje"},{n:3,t:"Estado inicial",d:"Revisión rápida general"}].map(s=><button key={s.n} className={`${step===s.n?"active":""} ${step>s.n?"done":""}`} onClick={()=>step>s.n&&setStep(s.n)}><span>{step>s.n?<Check size={15}/>:s.n}</span><div><b>{s.t}</b><small>{s.d}</small></div></button>)}</div></aside>
      <section className="onboarding-card"><div className="onboarding-progress"><span>PASO {step} DE 3</span><i><em style={{width:`${step/3*100}%`}}/></i><b>{Math.round(step/3*100)}%</b></div>
        {step===1&&<div className="onboarding-panel"><div className="onboarding-heading"><span><CarFront size={24}/></span><div><small>IDENTIFICACIÓN AUTOMÁTICA</small><h2>¿Cuál es tu vehículo?</h2><p>Usa el VIN o completa los datos manualmente.</p></div></div>
          <div className={`vin-lookup ${vinState}`}><div><small>NÚMERO VIN · OPCIONAL</small><label><input value={vehicle.vin} onChange={e=>{update("vin",e.target.value.toUpperCase().replace(/[^A-HJ-NPR-Z0-9]/g,"").slice(0,17));setVinState("idle")}} placeholder="17 caracteres"/><button type="button" disabled={vinState==="loading"} onClick={lookupVin}>{vinState==="loading"?"Consultando…":<><Search size={16}/>Identificar</>}</button></label></div>{vinState==="found"&&<span><Check size={16}/><b>Vehículo identificado</b><small>Confirma los datos encontrados.</small></span>}{vinState==="error"&&<span><AlertTriangle size={16}/><b>No pudimos identificarlo</b><small>Puedes continuar manualmente.</small></span>}</div>
          <div className="vehicle-type-grid">{["Carro","Moto","Camioneta","Taxi","Camión"].map(type=><button type="button" key={type} className={vehicle.type===type?"selected":""} onClick={()=>update("type",type)}><CarFront size={21}/><b>{type}</b>{vehicle.type===type&&<Check size={15}/>}</button>)}</div>
          <div className="onboarding-fields"><Field label="Marca" required><input value={vehicle.brand} onChange={e=>update("brand",e.target.value)} placeholder="Ej. Renault"/></Field><Field label="Modelo" required><input value={vehicle.model} onChange={e=>update("model",e.target.value)} placeholder="Ej. Duster"/></Field><Field label="Línea o versión"><input value={vehicle.version} onChange={e=>update("version",e.target.value)} placeholder="Ej. Intens 1.6"/></Field><Field label="Año" required><select value={vehicle.year} onChange={e=>update("year",e.target.value)}>{Array.from({length:27},(_,i)=>String(2026-i)).map(y=><option key={y}>{y}</option>)}</select></Field><Field label="Placa" required><input value={vehicle.plate} onChange={e=>update("plate",e.target.value.toUpperCase().slice(0,7))} placeholder="ABC 123"/></Field><Field label="Color"><input value={vehicle.color} onChange={e=>update("color",e.target.value)} placeholder="Ej. Gris grafito"/></Field></div>
          <div className="auto-photo"><figure><div className={`auto-photo-preview ${vehicle.imageUrl?"":"reference"}`}><img src={previewImage} alt={vehicle.imageUrl?`${vehicle.brand} ${vehicle.model}`:`Imagen de referencia para ${vehicle.type}`}/>{!vehicle.imageUrl&&<span>REFERENCIA AUTORAM</span>}</div><figcaption><b>{photoState==="loading"?"Procesando imagen…":vehicle.imageUrl?"Imagen del vehículo":`Referencia para ${vehicle.type}`}</b><small>{photoState==="error"?"No pudimos obtener la imagen; conservamos la referencia Autoram.":vehicle.imageAttribution||"Se usará si no subes una foto."}</small></figcaption></figure><div className="auto-photo-actions"><button type="button" disabled={!vehicle.brand||!vehicle.model||photoState==="loading"} onClick={()=>findImage()}><Search size={14}/>{vehicle.imageUrl?"Buscar otra":"Buscar imagen"}</button><label><Camera size={14}/>Subir foto<input type="file" accept="image/*" onChange={e=>void uploadImage(e.target.files?.[0])}/></label></div></div>
        </div>}
        {step===2&&<div className="onboarding-panel"><div className="onboarding-heading"><span><Gauge size={24}/></span><div><small>DATOS DE OPERACIÓN</small><h2>La información que mueve tus números</h2><p>El kilometraje será el punto de partida para alertas y servicios.</p></div></div><div className="onboarding-fields"><Field label="Tipo de combustible" required><select value={vehicle.fuel} onChange={e=>update("fuel",e.target.value)}><option>Gasolina corriente</option><option>Gasolina extra</option><option>ACPM / Diésel</option><option>Gas natural</option><option>Eléctrico</option><option>Híbrido</option></select></Field><Field label="Transmisión" required><select value={vehicle.transmission} onChange={e=>update("transmission",e.target.value)}><option>Automática</option><option>Manual</option><option>CVT</option><option>No aplica</option></select></Field><Field label="Kilometraje actual" required wide><div className="odometer-onboarding"><Gauge size={20}/><input type="number" min="0" value={vehicle.odometer} onChange={e=>update("odometer",e.target.value)} placeholder="35.782" autoFocus/><span>km</span></div></Field></div><div className="onboarding-tip"><TimerReset size={19}/><div><b>Este dato es clave</b><small>Activaremos recordatorios de aceite, llantas, frenos y revisiones.</small></div></div></div>}
        {step===3&&<div className="onboarding-panel"><div className="onboarding-heading"><span><ShieldCheck size={24}/></span><div><small>ESTADO INICIAL</small><h2>Una revisión rápida</h2><p>Indica cómo percibes hoy cada componente.</p></div></div><div className="health-list">{health.map(item=><div key={item.key}><span><item.icon size={19}/><b>{item.label}</b></span><div>{["Bueno","Por revisar","Urgente"].map(state=><button type="button" key={state} className={vehicle[item.key]===state?state==="Urgente"?"selected urgent":"selected":""} onClick={()=>update(item.key,state)}>{vehicle[item.key]===state&&<Check size={13}/>} {state}</button>)}</div></div>)}</div><div className="vehicle-summary"><div><CarFront size={28}/></div><span><small>LISTO PARA CREAR</small><b>{vehicle.brand} {vehicle.model}{vehicle.version?` ${vehicle.version}`:""} · {vehicle.plate}</b><em>{vehicle.color?`${vehicle.color} · `:""}{vehicle.odometer||"0"} km · Estado general {vehicle.general.toLowerCase()}</em></span></div></div>}
        {saveError&&<div className="form-error"><AlertTriangle size={16}/>{saveError}</div>}<div className="onboarding-actions">{step>1?<button type="button" onClick={()=>setStep(step-1)}><ArrowLeft size={17}/>Atrás</button>:<span/>}<button className="primary" type="button" disabled={(step===1&&!basicsReady)||(step===2&&!vehicle.odometer)||saving||photoState==="loading"} onClick={async()=>{if(step<3){setStep(step+1);return}setSaving(true);setSaveError("");try{await complete(vehicle)}catch(err){setSaveError(err instanceof Error?err.message:"No pudimos guardar el vehículo");setSaving(false)}}}>{step===3?<><Check size={17}/>{saving?"Guardando…":"Crear mi vehículo"}</>:<>Continuar<ChevronRight size={17}/></>}</button></div>
      </section>
    </div>
  </main>
}

export default function App() {
  const [stage, setStage] = useState<"loading"|"login"|"driver"|"onboarding"|"app">("loading");
  const [driver,setDriver]=useState<DriverProfile|null>(null);
  const [vehicle,setVehicle]=useState<VehicleProfile|null>(null);
  const [vehicles,setVehicles]=useState<VehicleProfile[]>([]);
  const [addingVehicle,setAddingVehicle]=useState(false);
  const [fuelRecords,setFuelRecords]=useState<FuelRecord[]>([]);const [maintenanceRecords,setMaintenanceRecords]=useState<MaintenanceRecord[]>([]);const [workSessions,setWorkSessions]=useState<WorkSessionRecord[]>([]);const [trips,setTrips]=useState<TripRecord[]>([]);const [quotes,setQuotes]=useState<ServiceQuoteRecord[]>([]);const [documents,setDocuments]=useState<VehicleDocumentRecord[]>([]);
  const [summary,setSummary]=useState<DashboardSummary|null>(null);
  const [syncError,setSyncError]=useState("");
  const [view, setView] = useState<View>("inicio");
  const [quick, setQuick] = useState(false);
  const [more, setMore] = useState(false);
  const [registerView, setRegisterView] = useState<View | null>(null);
  const [workActive, setWorkActive] = useState(false);
  const [workConfig, setWorkConfig] = useState<WorkConfig | null>(null);
  const [nowMs] = useState(() => Date.now());
  const loadAccount=useCallback(async()=>{const response=await autoramFetch("/api/autoram",{cache:"no-store"});const payload=await response.json();if(!response.ok)throw new Error(payload.error||"No pudimos abrir tu cuenta");setDriver(payload.driver||null);setVehicle(payload.vehicle||null);setVehicles(payload.vehicles||[]);setFuelRecords(payload.fuel||[]);setMaintenanceRecords(payload.maintenance||[]);setWorkSessions(payload.work||[]);setTrips(payload.trips||[]);setQuotes(payload.quotes||[]);setDocuments(payload.documents||[]);setSummary(payload.summary||null);const current=(payload.work||[]).find((session:WorkSessionRecord)=>!session.endedAt);setWorkActive(Boolean(current));setWorkConfig(current?{role:current.role,platforms:JSON.parse(current.platforms||"[]"),activity:current.activity||"",odometer:String(current.startOdometer)}:null);setStage(payload.driver?(payload.vehicle?"app":"onboarding"):"driver");setSyncError(payload.offline?"Sin señal: estás viendo la última copia guardada. Todo lo que registres se enviará al recuperar conexión.":"")},[]);
  useEffect(()=>{outbox.start(getSupabaseBrowserClient());return()=>outbox.stop()},[]);
  useVehicleRealtime(stage==="app"?getSupabaseBrowserClient():null,vehicle?.id||null,()=>{void loadAccount().catch(()=>undefined)});
  useEffect(()=>{let active=true;const supabase=getSupabaseBrowserClient();supabase.auth.getSession().then(({data})=>{if(!active)return;if(data.session)void loadAccount().catch(error=>{setSyncError(error instanceof Error?error.message:"No pudimos conectar");setStage("login")});else setStage("login")});const {data:listener}=supabase.auth.onAuthStateChange((event,session)=>{if(!active)return;if(event==="SIGNED_OUT"||!session)setStage("login");else if(event==="SIGNED_IN")void loadAccount()});return()=>{active=false;listener.subscription.unsubscribe()}},[loadAccount]);
  const post=async(action:string,data:unknown)=>{const response=await autoramFetch("/api/autoram",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action,data})});const payload=await response.json();if(!response.ok)throw new Error(payload.error||"No fue posible guardar");return payload};
  if(stage==="loading")return <main className="app-loading"><Brand/><span><i/></span><h1>Preparando tu centro de control</h1><p>Sincronizando perfil, vehículo e historial…</p></main>;
  if(stage==="login")return <LoginFlow authenticated={()=>void loadAccount()}/>;
  if(stage==="driver")return <DriverOnboarding complete={async d=>{await post("saveDriver",d);setDriver(d);setStage("onboarding")}}/>;
  if(stage==="onboarding")return <SmartVehicleOnboarding complete={async v=>{await post("saveVehicle",v);await loadAccount()}}/>;
  if(addingVehicle)return <SmartVehicleOnboarding cancel={()=>setAddingVehicle(false)} complete={async v=>{await post("addVehicle",v);setAddingVehicle(false);await loadAccount();setView("parque")}}/>;
  const firstName=driver?.fullName.trim().split(/\s+/)[0]||"Conductor";
  const initials=(driver?.fullName||"Conductor").trim().split(/\s+/).slice(0,2).map(n=>n[0]).join("").toUpperCase();
  return <main className="shell">
    <aside><Brand/><nav>{nav.map(n => <button key={n.id} className={view===n.id?"active":""} onClick={()=>setView(n.id)}><n.icon size={20}/>{n.label==="Mant."?"Mantenimiento":n.label==="Diag."?"Diagnóstico":n.label}</button>)}</nav><div className="side-bottom"><button className={view==="documentos"?"active":""} onClick={()=>setView("documentos")}><FileCheck2 size={20}/>Documentos{documents.some(item=>item.expiresAt&&new Date(`${item.expiresAt}T23:59:59`).getTime()-nowMs<31*86400000)&&<i/>}</button><button><Settings size={20}/>Configuración</button><button onClick={()=>void getSupabaseBrowserClient().auth.signOut()}><LogOut size={20}/>Cerrar sesión</button><div className="profile"><span>{initials}</span><div><b>{driver?.fullName||"Conductor"}</b><small>{driver?.city||"Colombia"} · Plan Fundador</small></div><ChevronRight size={17}/></div></div></aside>
    <section className="main"><header><div className="mobile-brand"><Brand/></div><div className="hello"><small>{driver?.city?.toUpperCase()||"COLOMBIA"} · PERFIL ACTIVO</small><h1>Hola, {firstName}</h1></div><div className="header-actions">{vehicles.length>1&&<select className="vehicle-switcher" aria-label="Vehículo activo" value={vehicle?.id||""} onChange={async e=>{try{await post("selectVehicle",{id:Number(e.target.value)});await loadAccount()}catch(error){setSyncError(error instanceof Error?error.message:"No pudimos cambiar de vehículo")}}}>{vehicles.map(item=><option key={item.id} value={item.id}>{item.brand} {item.model} · {item.plate}</option>)}</select>}<button className="icon" aria-label="Buscar"><Search size={18}/></button><button className="icon bell" aria-label="Notificaciones"><Bell size={18}/><i/></button><button className="primary" onClick={()=>setQuick(true)}><Plus size={18}/>Registrar</button></div></header>
      <div className="content"><SyncStatus/>{syncError&&<div className="sync-warning"><AlertTriangle size={16}/><span><b>Conexión pendiente</b><small>{syncError}</small></span></div>}{view==="inicio"&&<Dashboard summary={summary} go={setView} workActive={workActive} setWorkActive={setWorkActive} workConfig={workConfig} setWorkConfig={setWorkConfig} vehicle={vehicle} driver={driver} sessions={workSessions} fuelRecords={fuelRecords} maintenanceRecords={maintenanceRecords} trips={trips} documents={documents} activeSession={workSessions.find(session=>!session.endedAt)||null} startWork={async config=>{const payload=await post("startWork",config);setWorkSessions(v=>[payload.record,...v]);setWorkConfig(config);setWorkActive(true)}} finishWork={async data=>{const active=workSessions.find(session=>!session.endedAt);if(!active)return;const payload=await post("finishWork",{id:active.id,...data});setWorkSessions(v=>v.map(session=>session.id===active.id?{...session,endedAt:payload.endedAt,endOdometer:data.endOdometer,income:data.income,expenses:data.expenses}:session));setWorkActive(false)}}/>} {view==="parque"&&<FleetPage vehicles={vehicles} activeId={vehicle?.id||null} add={()=>setAddingVehicle(true)} select={async id=>{await post("selectVehicle",{id});await loadAccount()}}/>} {view==="tanqueos"&&<FuelPage vehicle={vehicle} records={fuelRecords} startOpen={registerView==="tanqueos"} consumed={()=>setRegisterView(null)} saveRecord={async record=>{const payload=await post("addFuel",record);setFuelRecords(v=>[{...record,id:Number(payload.id)},...v])}}/>} {view==="navegar"&&<NavigatePage vehicleId={vehicle?.id||null} records={trips} saveTrip={async record=>{const payload=await post("addTrip",record);setTrips(v=>[{...record,id:Number(payload.id)},...v])}}/>} {view==="mantenimiento"&&<MaintenancePage vehicle={vehicle} records={maintenanceRecords} startOpen={registerView==="mantenimiento"} consumed={()=>setRegisterView(null)} saveRecord={async record=>{const payload=await post("addMaintenance",record);setMaintenanceRecords(v=>[{...record,id:Number(payload.id)},...v])}}/>} {view==="diagnostico"&&<DiagnosticPage vehicle={vehicle}/>} {view==="documentos"&&<DocumentsPage vehicle={vehicle} records={documents} startOpen={registerView==="documentos"} consumed={()=>setRegisterView(null)} saveRecord={async record=>{const payload=await post("addDocument",record);setDocuments(v=>[{...record,id:Number(payload.id),createdAt:payload.createdAt},...v])}}/>} {view==="trabajo"&&<WorkPage sessions={workSessions} fuelRecords={fuelRecords} maintenanceRecords={maintenanceRecords} trips={trips} vehicle={vehicle} quotes={quotes} saveQuote={async record=>{const payload=await post("saveQuote",record);setQuotes(v=>[{...record,id:Number(payload.id),createdAt:payload.createdAt},...v])}}/>}</div>
    </section>
    <nav className="mobile-nav" aria-label="Navegación principal">{mobileNav.map(n=><button key={n.id} className={view===n.id?"active":""} onClick={()=>{setView(n.id);setMore(false)}}><n.icon size={22}/><small>{n.label}</small></button>)}<button className={more||["tanqueos","mantenimiento","diagnostico","documentos"].includes(view)?"active":""} onClick={()=>setMore(true)}><MoreHorizontal size={23}/><small>Más</small></button></nav>
    {quick&&<Quick close={()=>setQuick(false)} go={v=>{setView(v);setRegisterView(v)}}/>}
    {more&&<MoreMenu active={view} close={()=>setMore(false)} go={v=>{setView(v);setMore(false)}}/>}
  </main>
}

function FleetPage({vehicles,activeId,add,select}:{vehicles:VehicleProfile[];activeId:number|null;add:()=>void;select:(id:number)=>Promise<void>}) {
  const [busy,setBusy]=useState<number|null>(null);
  const [error,setError]=useState("");
  return <div className="page inner fleet-page">
    <PageTitle over="PARQUE AUTOMOTOR" title="Todos tus vehículos, una sola cuenta" text="Selecciona el vehículo que vas a usar. Sus tanqueos, recorridos, mantenimientos y números quedarán separados." action="Agregar vehículo" onAction={add}/>
    {error&&<div className="form-error"><AlertTriangle size={16}/>{error}</div>}
    <section className="fleet-grid">
      {vehicles.map(item=>{const active=item.id===activeId;const image=item.imageUrl||referenceVehicleImages[item.type]||referenceVehicleImages.Carro;return <article className={`card fleet-card ${active?"active":""}`} key={item.id}>
        <div className="fleet-photo"><img src={image} alt={`${item.brand} ${item.model}`}/><span>{active?"VEHÍCULO ACTIVO":item.type.toUpperCase()}</span></div>
        <div className="fleet-info"><div><small>{item.year} · {item.fuel}</small><h2>{item.brand} {item.model}</h2><p>{item.version||"Versión sin especificar"}</p></div><b>{item.plate}</b></div>
        <div className="fleet-stats"><span><small>ODÓMETRO</small><b>{Number(item.odometer).toLocaleString("es-CO")} km</b></span><span><small>ESTADO</small><b>{item.general}</b></span></div>
        <button disabled={active||busy!==null} onClick={async()=>{if(!item.id)return;setBusy(item.id);setError("");try{await select(item.id)}catch(reason){setError(reason instanceof Error?reason.message:"No pudimos activar el vehículo")}finally{setBusy(null)}}}>{active?<><Check size={16}/>En uso</>:busy===item.id?"Cambiando…":<>Usar este vehículo<ChevronRight size={16}/></>}</button>
      </article>})}
      <button className="fleet-add-card" onClick={add}><span><Plus size={24}/></span><b>Agregar otro vehículo</b><small>Carro, moto, camioneta o camión</small></button>
    </section>
  </div>
}

function Dashboard({summary,go,workActive,setWorkActive,workConfig,setWorkConfig,vehicle,driver,sessions,fuelRecords,maintenanceRecords,trips,documents,activeSession,startWork,finishWork}:{summary:DashboardSummary|null;go:(v:View)=>void;workActive:boolean;setWorkActive:(v:boolean)=>void;workConfig:WorkConfig|null;setWorkConfig:(v:WorkConfig)=>void;vehicle:VehicleProfile|null;driver:DriverProfile|null;sessions:WorkSessionRecord[];fuelRecords:FuelRecord[];maintenanceRecords:MaintenanceRecord[];trips:TripRecord[];documents:VehicleDocumentRecord[];activeSession:WorkSessionRecord|null;startWork:(config:WorkConfig)=>Promise<void>;finishWork:(data:{endOdometer:number;income:number;expenses:number})=>Promise<void>}) { const [now]=useState(()=>Date.now()),since=now-31*86400000,within=(date:string)=>new Date(date).getTime()>=since,closed=sessions.filter(session=>session.endedAt&&within(session.startedAt)),localIncome=closed.reduce((sum,session)=>sum+session.income,0),fuel=fuelRecords.filter(record=>within(record.occurredAt)).reduce((sum,record)=>sum+record.total,0),maintenance=maintenanceRecords.filter(record=>within(record.occurredAt)).reduce((sum,record)=>sum+record.total,0),other=closed.reduce((sum,session)=>sum+session.expenses,0),localExpenses=fuel+maintenance+other,localDistance=trips.filter(record=>within(record.startedAt)).reduce((sum,record)=>sum+record.distanceKm,0),income=summary?Number(summary.sessions.income):localIncome,expenses=summary?Number(summary.fuel.spent)+Number(summary.maintenance.spent)+Number(summary.sessions.expenses):localExpenses,distance=summary?Number(summary.trips.km):localDistance,vehicleImage=vehicle?.imageUrl||referenceVehicleImages[vehicle?.type||"Carro"]||referenceVehicleImages.Carro;return <div className="page dashboard-v19">
  <section className="dashboard-cockpit">
    <div className="cockpit-stripes" aria-hidden="true"><i/><i/><i/></div>
    <div className="cockpit-copy"><small>CENTRO DE CONTROL · 31 DÍAS</small><h2>{vehicle?`${vehicle.brand} ${vehicle.model}`:"Tu vehículo"}</h2><p>{vehicle?`${vehicle.year} · ${vehicle.fuel} · ${Number(vehicle.odometer||0).toLocaleString("es-CO")} km registrados`:"Registra un vehículo para comenzar a controlar sus costos."}</p><div className="cockpit-actions"><button className="cockpit-primary" onClick={()=>go("trabajo")}><CircleDollarSign size={19}/>Cotizar servicio</button><button onClick={()=>go("navegar")}><Navigation size={19}/>Iniciar recorrido</button></div></div>
    <div className="cockpit-vehicle"><img src={vehicleImage} alt={vehicle?`${vehicle.brand} ${vehicle.model}`:"Vehículo Autoram"}/><span>{vehicle?.plate||"SIN PLACA"}</span></div>
    <div className="cockpit-stats"><span><small>INGRESOS</small><b>{money.format(income)}</b></span><span><small>GASTOS</small><b>{money.format(expenses)}</b></span><span><small>RECORRIDO</small><b>{distance.toLocaleString("es-CO",{maximumFractionDigits:1})} km</b></span></div>
  </section>
  <div className="status status-compact"><span><i/>{workActive?"Jornada activa":"Datos protegidos"}<small>· {workActive?"registrando tu trabajo":"sincronizados"}</small></span><span><b>{driver?.city||"Colombia"}</b><small>Ubicación principal</small><MapPin size={17}/></span></div>
  <WorkLauncher active={workActive} setActive={setWorkActive} config={workConfig} setConfig={setWorkConfig} vehicle={vehicle} driver={driver} activeSession={activeSession} startWork={startWork} finishWork={finishWork}/>
  <section className="hero-grid"><Vehicle go={go} vehicle={vehicle} fuelRecords={fuelRecords}/><Profit go={go} income={income} expenses={expenses}/></section>
  <section className="metrics"><Metric icon={Fuel} label="Combustible · 31 días" value={money.format(fuel)} note={`${fuelRecords.filter(record=>within(record.occurredAt)).length} registros`} good/><Metric icon={Route} label="Distancia GPS" value={`${distance.toLocaleString("es-CO",{maximumFractionDigits:1})} km`} note={`${trips.filter(record=>within(record.startedAt)).length} recorridos`}/><Metric icon={Gauge} label="Jornadas cerradas" value={String(closed.length)} note="Historial real" good/><Metric icon={TimerReset} label="Mantenimiento" value={money.format(maintenance)} note={`${maintenanceRecords.filter(record=>within(record.occurredAt)).length} servicios`}/></section>
  <section className="lower"><WeeklyChart sessions={sessions} fuelRecords={fuelRecords} maintenanceRecords={maintenanceRecords}/><Alerts records={documents} go={()=>go("documentos")}/></section>
  <article className="card activity-card"><Title over="ACTIVIDAD RECIENTE" title="Últimos movimientos" action="Ver historial"/><div className="activity-grid">{fuelRecords[0]?<Movement icon={Fuel} title="Tanqueo registrado" meta={fuelRecords[0].station} amount={`-${money.format(fuelRecords[0].total)}`} time={new Date(fuelRecords[0].occurredAt).toLocaleDateString("es-CO",{day:"numeric",month:"short"})}/>:<Movement icon={Fuel} title="Sin tanqueos todavía" meta="Registra la primera carga" amount="$0" time="Pendiente"/>}{trips[0]?<Movement icon={Route} title="Recorrido GPS" meta={`${trips[0].distanceKm.toLocaleString("es-CO",{maximumFractionDigits:2})} km`} amount={formatDuration(trips[0].durationSeconds)} time={new Date(trips[0].startedAt).toLocaleDateString("es-CO",{day:"numeric",month:"short"})} good/>:<Movement icon={Route} title="Sin recorridos todavía" meta="Activa el GPS al iniciar" amount="0 km" time="Pendiente"/>}{maintenanceRecords[0]?<Movement icon={Wrench} title={maintenanceRecords[0].workDone} meta={maintenanceRecords[0].shop} amount={`-${money.format(maintenanceRecords[0].total)}`} time={new Date(maintenanceRecords[0].occurredAt).toLocaleDateString("es-CO",{day:"numeric",month:"short"})}/>:<Movement icon={Wrench} title="Sin servicios todavía" meta="Construye tu historial técnico" amount="$0" time="Pendiente"/>}</div></article>
  </div> }

function WorkLauncher({active,setActive,config,setConfig,vehicle,driver,activeSession,startWork,finishWork}:{active:boolean;setActive:(v:boolean)=>void;config:WorkConfig|null;setConfig:(v:WorkConfig)=>void;vehicle:VehicleProfile|null;driver:DriverProfile|null;activeSession:WorkSessionRecord|null;startWork:(config:WorkConfig)=>Promise<void>;finishWork:(data:{endOdometer:number;income:number;expenses:number})=>Promise<void>}) {
  const [elapsed,setElapsed]=useState(()=>activeSession?.startedAt?Math.max(0,Math.floor((Date.now()-new Date(activeSession.startedAt).getTime())/1000)):0); const [paused,setPaused]=useState(false);
  const [setup,setSetup]=useState(false);const [finishing,setFinishing]=useState(false);
  useEffect(()=>{if(!active||paused)return;const timer=setInterval(()=>setElapsed(v=>v+1),1000);return()=>clearInterval(timer)},[active,paused]);
  const h=String(Math.floor(elapsed/3600)).padStart(2,"0"),m=String(Math.floor(elapsed%3600/60)).padStart(2,"0"),s=String(elapsed%60).padStart(2,"0");
  if(!active)return <><section className="work-launch"><div className="work-launch-icon"><BriefcaseBusiness size={25}/></div><div><small>CONTROL DE JORNADA</small><h2>¿Listo para empezar a producir?</h2><p>Registra tiempo, kilómetros, ingresos y gastos desde el primer recorrido.</p></div><div className="platforms"><span>Uber</span><span>DiDi</span><span>inDrive</span><span>Independiente</span></div><button onClick={()=>setSetup(true)}><Play size={18} fill="currentColor"/>Iniciar jornada</button></section>{setup&&<WorkSetup vehicle={vehicle} city={driver?.city||"Colombia"} close={()=>setSetup(false)} start={async v=>{await startWork(v);setElapsed(0);setPaused(false);setConfig(v);setActive(true);setSetup(false)}}/>}</>;
  const mode=config?.role==="plataforma"?(config.platforms.join(" + ")||"Plataforma"):(config?.activity||"Independiente");
  return <><section className="work-launch active-work"><div className="work-pulse"><i/><BriefcaseBusiness size={23}/></div><div className="live-work-title"><small>JORNADA {paused?"PAUSADA":"ACTIVA"}</small><h2>{h}:{m}:{s}</h2><p>{mode} · {vehicle?.brand} {vehicle?.model} {vehicle?.plate} · desde {config?.odometer||vehicle?.odometer||"0"} km</p></div><div className="live-metrics"><span><small>TIEMPO</small><b>{Math.floor(elapsed/60)} min</b></span><span><small>ESTADO</small><b>Guardada</b></span><span><small>INICIO</small><b>{activeSession?new Date(activeSession.startedAt).toLocaleTimeString("es-CO",{hour:"numeric",minute:"2-digit"}):"Ahora"}</b></span></div><div className="work-controls"><button onClick={()=>setPaused(!paused)}><Pause size={17}/>{paused?"Continuar":"Pausar"}</button><button onClick={()=>setFinishing(true)}><Square size={16} fill="currentColor"/>Finalizar</button></div></section>{finishing&&<WorkFinish startOdometer={Number(config?.odometer||vehicle?.odometer||0)} close={()=>setFinishing(false)} finish={async data=>{await finishWork(data);setActive(false);setFinishing(false)}}/>}</>
}

function Vehicle({go,vehicle,fuelRecords}:{go:(v:View)=>void;vehicle:VehicleProfile|null;fuelRecords:FuelRecord[]}) { const brand=vehicle?.brand||"Tu vehículo",model=vehicle?.model||"",version=vehicle?.version||"",year=vehicle?.year||"",plate=vehicle?.plate||"Sin placa",color=vehicle?.color||"",fuel=vehicle?.fuel||"Sin combustible",odometer=vehicle?.odometer||"0",image=vehicle?.imageUrl||referenceVehicleImages[vehicle?.type||"Carro"]||referenceVehicleImages.Carro,attribution=vehicle?.imageAttribution||"Imagen de referencia Autoram",lastFuel=fuelRecords[0]; return <article className="card vehicle"><div className="vehicle-head"><div><small>MI VEHÍCULO</small><h2>{brand} {model}{version?` ${version}`:""}</h2><p>{year}{color?` · ${color}`:""} · {fuel}</p></div><b>{plate}</b></div><div className={`car-art has-photo ${vehicle?.imageUrl?"":"reference"}`}><img src={image} alt={`${brand} ${model} ${year}`}/><small>{attribution}</small></div><div className="vehicle-data real-data"><div className="ring pending"><span><Fuel size={15}/><b>—</b><small>SIN MEDIR</small></span></div><div><small>ODÓMETRO</small><strong>{Number(odometer).toLocaleString("es-CO")} <i>km</i></strong><p>Dato registrado</p></div><div><small>ÚLTIMO TANQUEO</small><strong>{lastFuel?new Date(lastFuel.occurredAt).toLocaleDateString("es-CO",{day:"numeric",month:"short"}):"Sin datos"}</strong><p>{lastFuel?money.format(lastFuel.total):"Registra la primera carga"}</p></div></div><button className="card-link" onClick={()=>go("diagnostico")}>Ver diagnóstico <ChevronRight size={16}/></button></article> }

function Profit({go,income,expenses}:{go:(v:View)=>void;income:number;expenses:number}) { const net=income-expenses,margin=income?Math.round(net/income*100):0;return <article className="profit"><div className="profit-head"><div><small>RENTABILIDAD · ÚLTIMOS 31 DÍAS</small><h2>{income?"Tu balance real":"Empieza tu primera jornada"}</h2></div><b><TrendingUp size={14}/>{margin}%</b></div><div className="profit-main"><small>GANANCIA NETA</small><strong>{money.format(net)}</strong><p>Después de combustible, servicios y otros gastos</p></div><div className="profit-bars"><div><span>Ingresos <b>{money.format(income)}</b></span><i style={{width:income?"100%":"0%"}}/></div><div><span>Gastos <b>{money.format(expenses)}</b></span><i style={{width:`${income?Math.min(100,expenses/income*100):0}%`}}/></div></div><div className="profit-foot"><span><small>Jornadas cerradas</small><b>{income?"Datos actualizados":"Sin datos todavía"}</b></span><i><em style={{width:`${Math.max(0,Math.min(100,margin))}%`}}/></i><button onClick={()=>go("trabajo")}>Ver detalle <ChevronRight size={15}/></button></div></article> }

function Metric({icon:Icon,label,value,note,good}:{icon:typeof Fuel,label:string,value:string,note:string,good?:boolean}) { return <article className="metric"><span><Icon size={20}/></span><div><small>{label}</small><b>{value}</b><em className={good?"good":""}>{good?<ArrowDownRight size={12}/>:<CalendarDays size={12}/>} {note}</em></div></article> }
function Title({over,title,action}:{over:string,title:string,action?:string}) { return <div className="title"><div><small>{over}</small><h2>{title}</h2></div>{action&&<button>{action}<ChevronRight size={15}/></button>}</div> }

function WeeklyChart({sessions,fuelRecords,maintenanceRecords}:{sessions:WorkSessionRecord[];fuelRecords:FuelRecord[];maintenanceRecords:MaintenanceRecord[]}) { const days=Array.from({length:7},(_,index)=>{const date=new Date();date.setHours(0,0,0,0);date.setDate(date.getDate()-(6-index));const end=new Date(date);end.setDate(end.getDate()+1);const inside=(value:string)=>{const time=new Date(value).getTime();return time>=date.getTime()&&time<end.getTime()};const income=sessions.filter(item=>item.endedAt&&inside(item.startedAt)).reduce((sum,item)=>sum+item.income,0);const expenses=sessions.filter(item=>item.endedAt&&inside(item.startedAt)).reduce((sum,item)=>sum+item.expenses,0)+fuelRecords.filter(item=>inside(item.occurredAt)).reduce((sum,item)=>sum+item.total,0)+maintenanceRecords.filter(item=>inside(item.occurredAt)).reduce((sum,item)=>sum+item.total,0);return {label:date.toLocaleDateString("es-CO",{weekday:"narrow"}).slice(0,1).toUpperCase(),income,expenses}}),maximum=Math.max(0,...days.flatMap(day=>[day.income,day.expenses])),income=days.reduce((sum,day)=>sum+day.income,0),expenses=days.reduce((sum,day)=>sum+day.expenses,0),balance=income-expenses;return <article className="card chart"><Title over="ÚLTIMOS 7 DÍAS" title="Ingresos frente a gastos"/>{maximum?<><div className="chart-balance"><span><i/>Ingresos</span><span><i/>Gastos</span><b>Balance <strong className={balance<0?"negative":""}>{balance>=0?"+":""}{money.format(balance)}</strong></b></div><div className="bars">{days.map((day,index)=><div key={index}><span><i style={{height:`${day.income/maximum*100}%`}}/><em style={{height:`${day.expenses/maximum*100}%`}}/></span><small>{day.label}</small></div>)}</div></>:<div className="chart-empty"><Activity size={25}/><b>Aún no hay movimientos esta semana</b><small>La gráfica aparecerá cuando registres ingresos o gastos reales.</small></div>}</article> }
function expiryCopy(value:string) { if(!value)return {note:"Sin fecha de vencimiento",tone:""};const today=new Date();today.setHours(0,0,0,0);const expiry=new Date(`${value}T23:59:59`),days=Math.ceil((expiry.getTime()-today.getTime())/86400000);if(days<0)return {note:`Venció hace ${Math.abs(days)} día${Math.abs(days)===1?"":"s"}`,tone:"danger"};if(days===0)return {note:"Vence hoy",tone:"warn"};if(days<=30)return {note:`Vence en ${days} día${days===1?"":"s"}`,tone:"warn"};return {note:`Vigente hasta ${expiry.toLocaleDateString("es-CO",{day:"numeric",month:"long",year:"numeric"})}`,tone:"ok"} }
function Alerts({records,go}:{records:VehicleDocumentRecord[];go:()=>void}) { const ordered=[...records].sort((a,b)=>a.expiresAt&&b.expiresAt?a.expiresAt.localeCompare(b.expiresAt):a.expiresAt?-1:1);return <article className="card alerts"><Title over="DOCUMENTOS REALES" title="Próximos vencimientos"/>{ordered.length?ordered.slice(0,3).map(record=>{const status=expiryCopy(record.expiresAt);return <Alert key={record.id||`${record.documentType}-${record.expiresAt}`} icon={status.tone==="warn"||status.tone==="danger"?AlertTriangle:ShieldCheck} title={record.documentType} note={status.note} tone={status.tone}/>;}):<div className="documents-empty"><FileCheck2 size={26}/><b>No has registrado documentos</b><small>Agrega el SOAT, la tecnomecánica u otro documento para activar alertas reales.</small></div>}<button className="ghost" onClick={go}>{ordered.length?"Ver documentos":"Agregar documentos"}</button></article> }
function Alert({icon:Icon,title,note,tone}:{icon:typeof Wrench,title:string,note:string,tone?:string}) { return <div className={`alert ${tone||""}`}><span><Icon size={19}/></span><div><b>{title}</b><small>{note}</small></div>{tone==="ok"?<Check size={17}/>:<ChevronRight size={17}/>}</div> }
function Movement({icon:Icon,title,meta,amount,time,good}:{icon:typeof Fuel,title:string,meta:string,amount:string,time:string,good?:boolean}) { return <div className="movement"><span><Icon size={18}/></span><div><b>{title}</b><small>{meta}</small></div><div><b className={good?"positive":""}>{amount}</b><small>{time}</small></div></div> }

function PageTitle({over,title,text,action,onAction}:{over:string,title:string,text:string,action?:string,onAction?:()=>void}) { return <div className="page-title"><div><small>{over}</small><h1>{title}</h1><p>{text}</p></div>{action&&<button className="primary" onClick={onAction}><Plus size={18}/>{action}</button>}</div> }

function FuelPage({vehicle,records,startOpen,consumed,saveRecord}:{vehicle:VehicleProfile|null;records:FuelRecord[];startOpen:boolean;consumed:()=>void;saveRecord:(record:FuelRecord)=>Promise<void>}) {
  const [open,setOpen]=useState(startOpen); const total=records.reduce((sum,record)=>sum+record.total,0);
  useEffect(()=>{if(!startOpen)return;const timer=setTimeout(()=>{setOpen(true);consumed()},0);return()=>clearTimeout(timer)},[startOpen,consumed]);
  return <div className="page inner"><PageTitle over="CONTROL DE COMBUSTIBLE" title="Cada galón bajo control" text="Rendimiento, gasto y autonomía calculados con tus registros." action="Nuevo tanqueo" onAction={()=>setOpen(true)}/><section className="detail-hero"><div><small>GASTO REGISTRADO</small><b>{money.format(total)}</b><em>{records.length} tanqueo{records.length===1?"":"s"} guardado{records.length===1?"":"s"}</em></div><div><Fuel size={38}/><b>{records.length?`${(records.reduce((s,r)=>s+r.gallons,0)/records.length).toFixed(1)}`:"0,0"} <i>gal/carga</i></b><small>Promedio por tanqueo</small></div><div><small>ÚLTIMO REGISTRO</small><b>{records[0]?new Date(records[0].occurredAt).toLocaleDateString("es-CO",{day:"numeric",month:"short"}):"Sin datos"}</b><em>{records[0]?`${records[0].odometer.toLocaleString("es-CO")} km`:"Registra tu primera carga"}</em></div></section><section className="two-col"><article className="card trend"><Title over="CONSUMO" title="Últimas cinco semanas"/><svg viewBox="0 0 600 180" role="img" aria-label="Tendencia de consumo"><path className="gridline" d="M0 30H600M0 90H600M0 150H600"/><path className="area" d="M0 128 C80 120 95 75 150 90 S250 135 310 85 S420 45 470 72 S550 110 600 45 L600 180 L0 180Z"/><path className="line" d="M0 128 C80 120 95 75 150 90 S250 135 310 85 S420 45 470 72 S550 110 600 45"/><circle cx="600" cy="45" r="6"/></svg><div className="axis"><span>Sem 1</span><span>Sem 2</span><span>Sem 3</span><span>Sem 4</span><span>Hoy</span></div></article><article className="card history"><Title over="HISTORIAL" title="Tanqueos recientes" action="Ver todos"/>{records.length?records.slice(0,4).map(record=><Movement key={record.id||`${record.occurredAt}-${record.station}`} icon={Fuel} title={`${record.station} · ${record.fuelType}`} meta={`${record.gallons.toLocaleString("es-CO")} gal · ${money.format(record.pricePerGallon)}/gal`} amount={`-${money.format(record.total)}`} time={new Date(record.occurredAt).toLocaleDateString("es-CO",{day:"numeric",month:"short"})}/>):<div className="empty-history"><Fuel size={24}/><b>Aún no hay tanqueos</b><small>El primer registro aparecerá aquí.</small></div>}</article></section>{open&&<FuelForm vehicle={vehicle} close={()=>setOpen(false)} save={async v=>{await saveRecord(v);setOpen(false)}}/>}</div>
}

function NavigatePage({vehicleId,records,saveTrip}:{vehicleId:number|null;records:TripRecord[];saveTrip:(record:TripRecord)=>Promise<void>}) {
  const tracker=useTripTracker({vehicleId});
  const [error,setError]=useState("");
  const [saving,setSaving]=useState(false);
  const [openTrip,setOpenTrip]=useState<number|null>(null);
  const running=tracker.state==="locating"||tracker.state==="tracking";
  const gpsState=tracker.state==="tracking"?"live":tracker.state==="locating"?"connecting":tracker.state==="error"?"error":"idle";
  const lastStored=records.find(record=>record.endLat!==null&&record.endLng!==null);
  const fallbackCenter:[number,number]|undefined=lastStored?[lastStored.endLng!,lastStored.endLat!]:undefined;
  const finish=async()=>{
    const trip=tracker.stop();
    if(!trip){setError("");return}
    setSaving(true);setError("");
    try{await saveTrip(trip);tracker.finish(true,navigator.onLine?"Recorrido guardado.":"Guardado en el teléfono. Se enviará cuando haya señal.")}
    catch(err){tracker.finish(false,"No pudimos guardar el recorrido.");setError(err instanceof Error?err.message:"No pudimos guardar el recorrido")}
    finally{setSaving(false)}
  };
  const totalKm=records.reduce((sum,record)=>sum+record.distanceKm,0),totalTime=records.reduce((sum,record)=>sum+record.durationSeconds,0),averageSpeed=totalTime?totalKm/(totalTime/3600):0;
  const recent=records.slice(0,5);
  return <div className="page inner"><PageTitle over="RECORRIDOS GPS" title="Tu recorrido sobre el mapa" text="Autoram dibuja tu ruta real y guarda distancia, tiempo y velocidad, incluso sin señal."/>
    {error&&<div className="sync-warning"><AlertTriangle size={16}/><span><b>Atención con el GPS</b><small>{error}</small></span></div>}
    {tracker.hasDraft&&!running&&<div className="sync-warning trip-draft"><Navigation size={16}/><span><b>Quedó un recorrido sin terminar</b><small>La app se cerró mientras registrabas. Puedes retomarlo o descartarlo.</small></span><button type="button" className="primary" onClick={tracker.resume}>Retomar</button><button type="button" onClick={tracker.discardDraft}>Descartar</button></div>}
    <section className={`nav-map-stage gps-${gpsState}`}>
      <TripMap points={tracker.points} live height="100%" fallbackCenter={fallbackCenter}/>
      {!running&&!tracker.points.length&&<div className="nav-map-wait"><LocateFixed size={25}/><b>Inicia para mostrar tu ubicación</b><small>El mapa seguirá tu recorrido en vivo</small></div>}
      <div className="nav-map-top"><span><i/>{gpsState==="live"?`GPS activo · precisión ${tracker.accuracyM} m`:gpsState==="connecting"?"Buscando señal…":gpsState==="error"?"GPS sin señal":"Listo para ubicarte"}</span><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer"><Map size={16}/>OpenStreetMap</a></div>
      <div className="trip"><div><small>RECORRIDO ACTUAL</small><b>{formatDuration(tracker.elapsed)}</b><em>{tracker.distanceKm.toLocaleString("es-CO",{minimumFractionDigits:2,maximumFractionDigits:2})} km{running?` · ${tracker.currentKmh} km/h`:""}{tracker.message?` · ${tracker.message}`:""}</em></div><button className={running?"stop":""} disabled={saving||tracker.state==="saving"} onClick={()=>running?void finish():tracker.start()}>{running?<><X size={19}/>{saving?"Guardando…":"Finalizar"}</>:<><Navigation size={19}/>Iniciar recorrido</>}</button></div>
    </section>
    <section className="metrics three"><Metric icon={Route} label="Distancia registrada" value={`${totalKm.toLocaleString("es-CO",{maximumFractionDigits:1})} km`} note={`${records.length} recorridos`}/><Metric icon={Gauge} label="Velocidad promedio" value={`${averageSpeed.toLocaleString("es-CO",{maximumFractionDigits:1})} km/h`} note="Según GPS"/><Metric icon={TimerReset} label="Tiempo en ruta" value={`${Math.round(totalTime/60)} min`} note="Historial guardado" good/></section>
    {recent.length>0&&<article className="card trip-history"><Title over="HISTORIAL" title="Últimos recorridos"/>{recent.map((trip,index)=>{const key=trip.id??index,open=openTrip===key,when=new Date(trip.startedAt);return <article key={key}><button type="button" className="movement" onClick={()=>setOpenTrip(open?null:key)} style={{width:"100%",textAlign:"left",background:"none",border:0,color:"inherit",cursor:"pointer"}}><span><Route size={18}/></span><div><b>{trip.distanceKm.toLocaleString("es-CO",{maximumFractionDigits:1})} km · {formatDuration(trip.durationSeconds)}</b><small>{when.toLocaleDateString("es-CO",{weekday:"short",day:"numeric",month:"short"})} · {when.toLocaleTimeString("es-CO",{hour:"2-digit",minute:"2-digit"})}{trip.avgSpeedKmh?` · ${trip.avgSpeedKmh} km/h prom.`:""}</small></div><div><b>{trip.routePoints?.length?"Ver ruta":"Sin ruta"}</b><small>{trip.id&&trip.id<0?"Pendiente de enviar":""}</small></div></button>{open&&<TripMap points={trip.routePoints||[]} height="240px"/>}</article>})}</article>}
  </div>
}

function MaintenancePage({vehicle,records,startOpen,consumed,saveRecord}:{vehicle:VehicleProfile|null;records:MaintenanceRecord[];startOpen:boolean;consumed:()=>void;saveRecord:(record:MaintenanceRecord)=>Promise<void>}) { const [open,setOpen]=useState(startOpen); useEffect(()=>{if(!startOpen)return;const timer=setTimeout(()=>{setOpen(true);consumed()},0);return()=>clearTimeout(timer)},[startOpen,consumed]); const last=records[0];return <div className="page inner"><PageTitle over="SALUD MECÁNICA" title="Historial de mantenimiento" text="El estado se construye únicamente con los servicios y reparaciones que registres." action="Registrar servicio" onAction={()=>setOpen(true)}/><section className="health"><article className="card health-score honest-score"><div className="score"><span><b>{records.length}</b><small>REG.</small></span></div><div><small>DATOS REALES</small><h2>{records.length?"Historial actualizado":"Sin servicios registrados"}</h2><p>{records.length?`${records.length} servicio${records.length===1?"":"s"} guardado${records.length===1?"":"s"} para este vehículo.`:"No asignaremos porcentajes de salud hasta tener información suficiente."}</p></div></article><article className="card next-service"><span><Wrench size={21}/></span><div><small>{last?"ÚLTIMO SERVICIO":"PRÓXIMO PASO"}</small><h3>{last?.workDone||"Registra el primer mantenimiento"}</h3><p>{last?`${last.shop} · ${money.format(last.total)} · ${last.odometer.toLocaleString("es-CO")} km`:"Incluye taller, costos, kilometraje y garantía."}</p></div><button onClick={()=>setOpen(true)}>Registrar</button></article></section>{records.length>0?<article className="card maintenance-history"><Title over="HISTORIAL REAL" title="Servicios registrados"/>{records.slice(0,5).map(record=><Movement key={record.id||`${record.occurredAt}-${record.shop}`} icon={Wrench} title={record.workDone} meta={`${record.shop} · ${record.odometer.toLocaleString("es-CO")} km`} amount={`-${money.format(record.total)}`} time={new Date(record.occurredAt).toLocaleDateString("es-CO",{day:"numeric",month:"short"})}/>)}</article>:<article className="card maintenance-empty"><Wrench size={28}/><b>Aún no hay datos mecánicos</b><small>Registra el primer servicio para comenzar un historial confiable.</small></article>}{open&&<MaintenanceForm vehicle={vehicle} close={()=>setOpen(false)} save={async v=>{await saveRecord(v);setOpen(false)}}/>}</div> }
function Service({icon:Icon,title,health,note}:{icon:typeof Activity,title:string,health:number,note:string}) { return <article className="card service"><div><span><Icon size={20}/></span><b>{health}%</b></div><h3>{title}</h3><p>{note}</p><i><em style={{width:`${health}%`}}/></i></article> }

function DocumentsPage({vehicle,records,startOpen,consumed,saveRecord}:{vehicle:VehicleProfile|null;records:VehicleDocumentRecord[];startOpen:boolean;consumed:()=>void;saveRecord:(record:VehicleDocumentRecord)=>Promise<void>}) {
  const [open,setOpen]=useState(startOpen);
  const [nowMs] = useState(() => Date.now());
  useEffect(()=>{if(!startOpen)return;const timer=setTimeout(()=>{setOpen(true);consumed()},0);return()=>clearTimeout(timer)},[startOpen,consumed]);
  const ordered=[...records].sort((a,b)=>a.expiresAt&&b.expiresAt?a.expiresAt.localeCompare(b.expiresAt):a.expiresAt?-1:1);
  return <div className="page inner documents-page"><PageTitle over="DOCUMENTOS DEL VEHÍCULO" title="Vencimientos bajo control" text={`Registra únicamente los documentos reales de ${vehicle?.brand||"tu vehículo"} ${vehicle?.model||""}. Autoram te avisará según las fechas que ingreses.`} action="Registrar documento" onAction={()=>setOpen(true)}/>
    <section className="document-summary"><article className="card"><span><FileCheck2 size={24}/></span><div><small>DOCUMENTOS GUARDADOS</small><b>{records.length}</b><p>{records.length?"Datos del vehículo activo":"Aún no hay documentos"}</p></div></article><article className="card"><span><AlertTriangle size={24}/></span><div><small>VENCEN EN 30 DÍAS</small><b>{records.filter(item=>{if(!item.expiresAt)return false;const days=Math.ceil((new Date(`${item.expiresAt}T23:59:59`).getTime()-nowMs)/86400000);return days>=0&&days<=30}).length}</b><p>Calculado con tus fechas</p></div></article><article className="card"><span><ShieldCheck size={24}/></span><div><small>VIGENTES</small><b>{records.filter(item=>item.expiresAt&&new Date(`${item.expiresAt}T23:59:59`).getTime()>nowMs).length}</b><p>Sin datos inventados</p></div></article></section>
    <article className="card document-list"><Title over="HISTORIAL DOCUMENTAL" title={records.length?"Documentos registrados":"Registra el primer documento"}/>{ordered.length?<div>{ordered.map(record=>{const status=expiryCopy(record.expiresAt);return <div className={`document-row ${status.tone}`} key={record.id||`${record.documentType}-${record.expiresAt}`}><span>{status.tone==="warn"||status.tone==="danger"?<AlertTriangle size={20}/>:<FileCheck2 size={20}/>}</span><div><b>{record.documentType}</b><small>{record.documentNumber?`N.º ${record.documentNumber}`:"Sin número registrado"}{record.provider?` · ${record.provider}`:""}</small></div><div><b>{status.note}</b><small>{record.issuedAt?`Expedido: ${new Date(`${record.issuedAt}T12:00:00`).toLocaleDateString("es-CO")}`:"Fecha de expedición no registrada"}</small></div></div>})}</div>:<div className="documents-page-empty"><FileCheck2 size={34}/><b>La información se mostrará después de registrarla</b><small>Autoram no volverá a mostrar SOAT, tecnomecánica ni fechas que usted no haya ingresado.</small><button className="primary" onClick={()=>setOpen(true)}><Plus size={17}/>Agregar documento</button></div>}</article>
    {open&&<DocumentForm vehicle={vehicle} close={()=>setOpen(false)} save={async record=>{await saveRecord(record);setOpen(false)}}/>}
  </div>
}

const dtcLibrary:Record<string,{title:string;system:string;severity:"media"|"alta";summary:string;causes:string[];components:string[]}>= {
  P0300:{title:"Fallo de encendido aleatorio",system:"Motor · Combustión",severity:"alta",summary:"La computadora detectó combustiones irregulares en uno o varios cilindros.",causes:["Bujías desgastadas","Bobina o cable de encendido","Inyector sucio o mezcla incorrecta"],components:["Bujías","Bobinas","Inyectores"]},
  P0301:{title:"Fallo de encendido en cilindro 1",system:"Motor · Cilindro 1",severity:"alta",summary:"El cilindro número 1 no está realizando la combustión de forma estable.",causes:["Bujía desgastada o contaminada","Bobina de encendido defectuosa","Problema de inyección o compresión"],components:["Bujía cilindro 1","Bobina de encendido","Inyector"]},
  P0171:{title:"Mezcla demasiado pobre",system:"Motor · Combustible",severity:"media",summary:"El motor está recibiendo demasiado aire o menos combustible del necesario.",causes:["Fuga de vacío","Sensor MAF sucio","Baja presión de combustible"],components:["Sensor MAF","Mangueras de vacío","Filtro de combustible"]},
  P0420:{title:"Eficiencia baja del catalizador",system:"Emisiones · Banco 1",severity:"media",summary:"El sistema detecta que el catalizador no está reduciendo emisiones como debería.",causes:["Catalizador deteriorado","Sensor de oxígeno lento","Fuga en el escape"],components:["Sensor de oxígeno","Catalizador","Empaque de escape"]},
  P0562:{title:"Voltaje bajo del sistema",system:"Sistema eléctrico",severity:"alta",summary:"El voltaje disponible estuvo por debajo del nivel esperado mientras el vehículo funcionaba.",causes:["Batería descargada","Alternador con carga insuficiente","Conexiones flojas o sulfatadas"],components:["Batería","Alternador","Terminales"]},
  P0128:{title:"Temperatura de refrigerante baja",system:"Motor · Refrigeración",severity:"media",summary:"El motor tardó demasiado en alcanzar su temperatura normal de funcionamiento.",causes:["Termostato abierto","Sensor de temperatura incorrecto","Nivel bajo de refrigerante"],components:["Termostato","Sensor ECT","Refrigerante"]}
};

function DiagnosticPage({vehicle}:{vehicle:VehicleProfile|null}) {
  const [code,setCode]=useState("P0301");
  const [searched,setSearched]=useState("P0301");
  const result=dtcLibrary[searched];
  const runSearch=()=>setSearched(code.trim().toUpperCase());
  const car=`${vehicle?.brand||"Renault"} ${vehicle?.model||"Duster"} ${vehicle?.year||"2024"}`;
  return <div className="page inner diagnostic-page"><PageTitle over="DIAGNÓSTICO INTELIGENTE" title="Entiende qué le pasa a tu vehículo" text="Consulta códigos OBD-II en lenguaje claro y conoce qué componentes deben revisarse."/>
    <section className="scanner-banner"><div className="scanner-pulse"><Activity size={24}/><i/></div><div><small>LECTURA OBD2</small><h2>Escáner inalámbrico próximamente</h2><p>La conexión ELM327 permitirá leer códigos directamente desde el vehículo.</p></div><button disabled><Navigation size={17}/>Conectar escáner</button></section>
    <section className="diagnostic-grid"><article className="card code-search-card"><small>CONSULTA MANUAL</small><h2>Ingresa el código de falla</h2><p>Lo encuentras en un escáner OBD2 o en el reporte del taller.</p><form onSubmit={e=>{e.preventDefault();runSearch()}}><label><Activity size={21}/><input value={code} onChange={e=>setCode(e.target.value.toUpperCase().replace(/[^A-Z0-9]/g,"").slice(0,5))} placeholder="Ej. P0301" aria-label="Código OBD2"/><button type="submit"><Search size={17}/>Analizar</button></label></form><div className="popular-codes"><span>PRUEBA UN EJEMPLO</span>{Object.keys(dtcLibrary).map(c=><button key={c} className={searched===c?"active":""} onClick={()=>{setCode(c);setSearched(c)}}>{c}</button>)}</div><div className="vehicle-context"><CarFront size={20}/><span><b>{car}</b><small>{vehicle?.vin?`VIN terminado en ${vehicle.vin.slice(-6)}`:"Perfil manual del vehículo"}</small></span><Check size={16}/></div></article>
      <article className={`card diagnostic-result ${!result?"empty":""}`}>{result?<><div className="result-head"><span className={result.severity}><AlertTriangle size={21}/></span><div><small>{result.system}</small><h2>{searched} · {result.title}</h2></div><b className={result.severity}>PRIORIDAD {result.severity.toUpperCase()}</b></div><p className="result-summary">{result.summary}</p><div className="result-section"><small>POSIBLES CAUSAS</small>{result.causes.map((cause,i)=><div key={cause}><span>{i+1}</span><b>{cause}</b></div>)}</div><div className="safety-callout"><ShieldCheck size={19}/><span><b>No cambies piezas todavía</b><small>El código orienta la revisión, pero no confirma por sí solo cuál componente está dañado.</small></span></div></>:<><div className="empty-code"><Search size={31}/><h2>Código no disponible</h2><p>La primera biblioteca del prototipo incluye los códigos de ejemplo visibles. La base completa se incorporará en la siguiente capa de datos.</p></div></>}</article>
    </section>
    {result&&<section className="parts-section"><div className="parts-heading"><div><small>COMPONENTES RELACIONADOS</small><h2>Qué debería revisar el técnico</h2></div><span>Compatibilidad por confirmar con VIN</span></div><div className="part-cards">{result.components.map((part,i)=><article className="card part-card" key={part}><span><Wrench size={20}/></span><div><small>COMPONENTE {String(i+1).padStart(2,"0")}</small><h3>{part}</h3><p>Posiblemente relacionado con {searched}. Requiere verificación técnica.</p></div><a href={`https://listado.mercadolibre.com.co/${encodeURIComponent(`${part} ${car}`).replace(/%20/g,"-")}`} target="_blank" rel="noreferrer">Buscar referencia <ChevronRight size={15}/></a></article>)}</div></section>}
    <div className="diagnostic-disclaimer"><AlertTriangle size={17}/><p>Autoram ofrece información orientativa. Si hay pérdida de potencia, temperatura alta, olor a combustible, humo o testigo rojo, detén el vehículo y solicita revisión profesional.</p></div>
  </div>
}

type RoutePoint={lat:number;lng:number};
type RouteStatus="idle"|"locating"|"calculating"|"ready"|"error";
type DestinationCandidate={point:RoutePoint;label:string;distanceKm:number};

function RoutePricingCalculator({sessions,fuelRecords,maintenanceRecords,vehicle,quotes,saveQuote}:{sessions:WorkSessionRecord[];fuelRecords:FuelRecord[];maintenanceRecords:MaintenanceRecord[];trips:TripRecord[];vehicle:VehicleProfile|null;quotes:ServiceQuoteRecord[];saveQuote:(record:ServiceQuoteRecord)=>Promise<void>}) {
  const sortedFuel=[...fuelRecords].sort((a,b)=>a.odometer-b.odometer);
  const recentFuel=[...fuelRecords].sort((a,b)=>new Date(b.occurredAt).getTime()-new Date(a.occurredAt).getTime())[0];
  const measuredEfficiencies=sortedFuel.slice(1).map((record,index)=>(record.odometer-sortedFuel[index].odometer)/record.gallons).filter(value=>value>=5&&value<=150);
  const measuredEfficiency=measuredEfficiencies.length?measuredEfficiencies.reduce((sum,value)=>sum+value,0)/measuredEfficiencies.length:0;
  const historicalKm=sessions.filter(session=>session.endedAt&&session.endOdometer!==null).reduce((sum,session)=>sum+Math.max(0,(session.endOdometer||0)-session.startOdometer),0);
  const measuredWear=historicalKm?Math.round(maintenanceRecords.reduce((sum,record)=>sum+record.total,0)/historicalKm):0;
  const initialOdometer=Number(vehicle?.odometer||sessions[0]?.endOdometer||sessions[0]?.startOdometer||0);
  const [serviceName,setServiceName]=useState("Servicio particular");
  const [destination,setDestination]=useState("");
  const [destinationLabel,setDestinationLabel]=useState("");
  const [destinationPoint,setDestinationPoint]=useState<RoutePoint|null>(null);
  const [destinationCandidates,setDestinationCandidates]=useState<DestinationCandidate[]>([]);
  const [origin,setOrigin]=useState<RoutePoint|null>(null);
  const [routeGeometry,setRouteGeometry]=useState<[number,number][]|null>(null);
  const [searchingPlace,setSearchingPlace]=useState(false);
  const [routeStatus,setRouteStatus]=useState<RouteStatus>("idle");
  const [routeMessage,setRouteMessage]=useState("Usa tu ubicación y escribe el destino.");
  const [oneWayKm,setOneWayKm]=useState(0);
  const [oneWayMinutes,setOneWayMinutes]=useState(0);
  const [roundTrip,setRoundTrip]=useState(false);
  const [serviceZone,setServiceZone]=useState<"urban"|"rural">("urban");
  const [urbanRate,setUrbanRate]=useState("1500");
  const [ruralRate,setRuralRate]=useState("2000");
  const [manualDistance,setManualDistance]=useState(false);
  const [manualKm,setManualKm]=useState("");
  const [fuelPrice,setFuelPrice]=useState(String(recentFuel?.pricePerGallon||0));
  const [efficiency,setEfficiency]=useState(String(measuredEfficiency?Math.round(measuredEfficiency*10)/10:35));
  const [wearPerKm,setWearPerKm]=useState(String(measuredWear||300));
  const [tolls,setTolls]=useState("0");
  const [otherCosts,setOtherCosts]=useState("0");
  const [hourlyRate,setHourlyRate]=useState("0");
  const [commission,setCommission]=useState("0");
  const [margin,setMargin]=useState("25");
  const [finalPrice,setFinalPrice]=useState("");
  const [priceEdited,setPriceEdited]=useState(false);
  const [saving,setSaving]=useState(false);
  const [saved,setSaved]=useState(false);
  const [error,setError]=useState("");
  const [shareMessage,setShareMessage]=useState("");

  const serviceKm=Math.round(oneWayKm*(roundTrip?2:1)*10)/10;
  const routeHours=Math.round(oneWayMinutes*(roundTrip?2:1)/6)/10;
  const efficiencyValue=Math.max(.1,Number(efficiency)||0);
  const fuelCost=Math.round(serviceKm/efficiencyValue*(Number(fuelPrice)||0));
  const wearCost=Math.round(serviceKm*(Number(wearPerKm)||0));
  const timeCost=Math.round(routeHours*(Number(hourlyRate)||0));
  const extrasCost=(Number(tolls)||0)+(Number(otherCosts)||0);
  const operatingCost=fuelCost+wearCost+timeCost+extrasCost;
  const combinedPct=(Number(commission)||0)+(Number(margin)||0);
  const validPercent=combinedPct<95;
  const costBasedPrice=validPercent&&serviceKm>0?Math.ceil((operatingCost/Math.max(.05,1-combinedPct/100))/1000)*1000:0;
  const minimumRate=serviceZone==="urban"?(Number(urbanRate)||0):(Number(ruralRate)||0);
  const commercialSubtotal=serviceKm*minimumRate+(Number(tolls)||0)+(Number(otherCosts)||0);
  const commercialPrice=serviceKm>0?Math.ceil((commercialSubtotal/Math.max(.05,1-(Number(commission)||0)/100))/1000)*1000:0;
  const recommendedPrice=Math.max(costBasedPrice,commercialPrice);
  const minimumRateApplied=commercialPrice>=costBasedPrice&&commercialPrice>0;

  const displayedPrice=priceEdited?finalPrice:String(recommendedPrice);
  const selectedPrice=Math.max(0,Number(displayedPrice)||0);
  const commissionAmount=Math.round(selectedPrice*(Number(commission)||0)/100);
  const expectedProfit=Math.round(selectedPrice-operatingCost-commissionAmount);
  const pricePerKm=serviceKm?Math.round(selectedPrice/serviceKm):0;
  const compactDestination=(destinationLabel||destination).split(",").slice(0,3).join(",");

  const getCurrentLocation=async()=>{
    setError("");
    setRouteStatus("locating");
    setRouteMessage("Buscando tu ubicación actual…");
    if(!navigator.geolocation){setRouteStatus("error");setRouteMessage("Este navegador no permite usar ubicación.");setManualDistance(true);throw new Error("Ubicación no disponible")}
    return await new Promise<RoutePoint>((resolve,reject)=>navigator.geolocation.getCurrentPosition(position=>{
      const point={lat:position.coords.latitude,lng:position.coords.longitude};
      setOrigin(point);setRouteStatus("idle");setRouteMessage("Ubicación actual lista.");resolve(point);
    },()=>{
      setRouteStatus("error");setRouteMessage("No pudimos acceder al GPS. Puedes escribir los kilómetros manualmente.");setManualDistance(true);reject(new Error("Permiso de ubicación no concedido"));
    },{enableHighAccuracy:true,timeout:12000,maximumAge:60000}));
  };

  const lookupDestination=async(searchOrigin:RoutePoint)=>{
    if(!destination.trim())throw new Error("Escribe una dirección, un barrio o el nombre del lugar.");
    const places=await searchAddress(destination,searchOrigin);
    return places.map(place=>{const point={lat:place.lat,lng:place.lng};return {point,label:place.label,distanceKm:haversineKm(searchOrigin,point)}}).sort((a,b)=>a.distanceKm-b.distanceKm).slice(0,4);
  };

  const showDestinationOnMap=async()=>{
    setError("");setSearchingPlace(true);setRouteMessage("Buscando el destino en el mapa…");
    try{
      const searchOrigin=origin||await getCurrentLocation();
      const results=await lookupDestination(searchOrigin),result=results[0];
      setDestinationCandidates(results);setDestinationPoint(result.point);setDestinationLabel(result.label);setRouteGeometry(null);setOneWayKm(0);setOneWayMinutes(0);setRouteStatus("idle");setRouteMessage(results.length>1?"Elige la coincidencia correcta y confirma la ruta.":"Destino marcado. Toca el mapa si necesitas mover el punto.");
    }catch(searchError){setRouteStatus("error");setRouteMessage("No encontramos el destino en el mapa.");setError(searchError instanceof Error?searchError.message:"No pudimos buscar el destino")}
    finally{setSearchingPlace(false)}
  };

  const calculateRoute=async()=>{
    setError("");setSaved(false);setShareMessage("");
    if(!destinationPoint&&!destination.trim()){setError("Busca una dirección o selecciona el destino en el mapa.");return}
    try{
      const start=origin||await getCurrentLocation();
      setRouteStatus("calculating");setRouteMessage("Calculando la ruta desde tu ubicación…");
      const results=destinationPoint?null:await lookupDestination(start);
      const located=destinationPoint?{point:destinationPoint,label:destinationLabel||destination}:results![0];
      const end=located.point;
      const routeResponse=await fetch(`https://router.project-osrm.org/route/v1/driving/${start.lng},${start.lat};${end.lng},${end.lat}?overview=full&geometries=geojson&steps=false`);
      if(!routeResponse.ok)throw new Error("No pudimos calcular la ruta.");
      const routeData=await routeResponse.json() as {code:string;routes?:Array<{distance:number;duration:number;geometry?:{coordinates:[number,number][]}}>};
      if(routeData.code!=="Ok"||!routeData.routes?.[0])throw new Error("No encontramos una ruta en carro para ese destino.");
      setDestinationPoint(end);setDestinationLabel(located.label);setRouteGeometry(routeData.routes[0].geometry?.coordinates||null);
      setOneWayKm(Math.round(routeData.routes[0].distance/100)/10);
      setOneWayMinutes(Math.max(1,Math.round(routeData.routes[0].duration/60)));
      setManualDistance(false);setPriceEdited(false);setRouteStatus("ready");setRouteMessage("Ruta calculada. Ya puedes revisar tus costos.");
    }catch(routeError){
      setRouteStatus("error");setManualDistance(true);setRouteMessage("La ruta automática no respondió. Ingresa la distancia para continuar.");setError(routeError instanceof Error?routeError.message:"No pudimos calcular la ruta");
    }
  };

  const selectMapDestination=(selected:LatLng)=>{
    setDestinationPoint(selected);setRouteGeometry(null);setDestinationLabel(destination.trim()?`${destination.trim()} · punto ajustado`:"Destino seleccionado en el mapa");
    if(!destination.trim())setDestination("Destino seleccionado en el mapa");
    setOneWayKm(0);setOneWayMinutes(0);setPriceEdited(false);setRouteStatus("idle");setRouteMessage("Punto seleccionado. Presiona calcular para obtener la ruta y el precio.");
  };
  const chooseDestinationCandidate=(candidate:DestinationCandidate)=>{
    setDestinationPoint(candidate.point);setDestinationLabel(candidate.label);setRouteGeometry(null);setOneWayKm(0);setOneWayMinutes(0);setPriceEdited(false);setRouteStatus("idle");setRouteMessage("Destino confirmado. Ahora calcula la ruta y el precio.");
  };

  const applyManualKm=(value:string)=>{setManualKm(value);setOneWayKm(Math.max(0,Number(value)||0));setOneWayMinutes(0);setDestinationLabel(destination.trim());setPriceEdited(false);setRouteStatus(Number(value)>0?"ready":"error");setRouteMessage(Number(value)>0?"Distancia manual aplicada.":"Escribe una distancia mayor a cero.")};
  const resetSuggestedPrice=()=>{setPriceEdited(false);setFinalPrice("")};
  const quoteText=[
    "Cotización Autoram",
    serviceName.trim()||"Servicio particular",
    `Ruta: ubicación actual → ${compactDestination||"destino"}`,
    `Recorrido: ${serviceKm.toLocaleString("es-CO",{maximumFractionDigits:1})} km${roundTrip?" · ida y regreso":" · solo ida"}`,
    `Tarifa: ${serviceZone==="urban"?"urbana":"rural"} · ${money.format(minimumRate)}/km`,
    `Precio del servicio: ${money.format(selectedPrice)}`,
    "Valor estimado con combustible, desgaste, tiempo, peajes y comisión registrados."
  ].join("\n");

  const shareQuote=async()=>{
    setShareMessage("");
    if(!selectedPrice||!serviceKm){setError("Calcula la ruta y define el precio antes de enviarlo.");return}
    try{
      if(navigator.share){await navigator.share({title:"Cotización Autoram",text:quoteText});setShareMessage("Cotización enviada.");return}
      window.open(`https://wa.me/?text=${encodeURIComponent(quoteText)}`,"_blank","noopener,noreferrer");setShareMessage("Cotización abierta para enviar.");
    }catch(shareError){if(shareError instanceof DOMException&&shareError.name==="AbortError")return;try{await navigator.clipboard.writeText(quoteText);setShareMessage("Cotización copiada para compartir.")}catch{setError("No pudimos abrir las opciones para compartir.")}}
  };

  const record:ServiceQuoteRecord={serviceName:serviceName.trim()||"Servicio particular",createdAt:new Date().toISOString(),startOdometer:initialOdometer,endOdometer:initialOdometer+serviceKm,serviceKm,extraKm:0,totalKm:serviceKm,fuelPrice:Number(fuelPrice)||0,efficiencyKpg:efficiencyValue,fuelCost,wearPerKm:Number(wearPerKm)||0,wearCost,tolls:Number(tolls)||0,otherCosts:Number(otherCosts)||0,hours:routeHours,hourlyRate:Number(hourlyRate)||0,timeCost,commissionPct:Number(commission)||0,marginPct:Number(margin)||0,operatingCost,recommendedPrice:selectedPrice,pricePerKm};

  return <section className="work-pricing">
    <div className="work-pricing-intro"><div><small>COTIZACIÓN INTELIGENTE</small><h2>Del destino al precio, sin sacar cuentas</h2><p>Autoram mide la ruta y convierte cada gasto del vehículo en un precio claro para tu cliente.</p></div><div className="work-pricing-steps" aria-label="Pasos de la cotización"><span className="active"><b>1</b>Ruta</span><i/><span className={serviceKm?"active":""}><b>2</b>Costos</span><i/><span className={selectedPrice?"active":""}><b>3</b>Enviar</span></div></div>
    <div className="work-pricing-layout">
      <article className="work-route-card">
        <div className="work-route-stripes" aria-hidden="true"><i/><i/><i/></div>
        <div className="work-route-title"><span><Route size={22}/></span><div><small>PASO 1 · ARMA LA RUTA</small><h3>¿A dónde vas?</h3></div></div>
        <label className="work-service-name"><span>Nombre del servicio</span><input value={serviceName} onChange={event=>setServiceName(event.target.value)} placeholder="Ej. Traslado al aeropuerto"/></label>
        <div className="work-route-line">
          <div className="work-route-stop origin"><i/><div><small>SALIDA</small><b>{origin?"Ubicación actual lista":"Tu ubicación actual"}</b><span>{origin?"GPS conectado":"Autoriza el GPS solo al calcular"}</span></div><button type="button" onClick={()=>getCurrentLocation().catch(()=>undefined)} disabled={routeStatus==="locating"||routeStatus==="calculating"}><LocateFixed size={18}/>{routeStatus==="locating"?"Buscando…":origin?"Actualizar":"Usar ubicación"}</button></div>
          <div className="work-route-track" aria-hidden="true"><span/><i/><span/></div>
          <div className="work-route-stop destination"><i/><label><small>DESTINO</small><input value={destination} onChange={event=>{setDestination(event.target.value);setDestinationLabel("");setDestinationPoint(null);setDestinationCandidates([]);setRouteGeometry(null);setOneWayKm(0)}} placeholder="Lugar, barrio y ciudad"/></label><button type="button" onClick={showDestinationOnMap} disabled={searchingPlace||routeStatus==="calculating"}><Search size={17}/>{searchingPlace?"Buscando…":"Buscar cerca"}</button></div>
        </div>
        <div className="work-map-shell">
          <div className="work-map-toolbar"><div><Map size={18}/><span><b>Selecciona el destino</b><small>Busca arriba o toca cualquier punto del mapa</small></span></div><span className={destinationPoint?"selected":""}>{destinationPoint?"Punto listo":"Sin seleccionar"}</span></div>
          <DestinationMap origin={origin} destination={destinationPoint} route={routeGeometry} onSelect={selectMapDestination} height="285px"/>
          <div className="work-map-selection"><MapPin size={17}/><span>{destinationPoint?(destinationLabel||"Destino seleccionado"):"Busca una dirección o marca el punto directamente"}</span></div>
        </div>
        {destinationCandidates.length>1&&<div className="work-place-results"><div><b>¿Cuál de estos lugares es?</b><small>Ordenados desde tu ubicación actual</small></div>{destinationCandidates.map((candidate,index)=><button type="button" key={`${candidate.point.lat}-${candidate.point.lng}`} className={destinationPoint?.lat===candidate.point.lat&&destinationPoint?.lng===candidate.point.lng?"active":""} onClick={()=>chooseDestinationCandidate(candidate)}><span>{index+1}</span><p><b>{candidate.label.split(",")[0]}</b><small>{candidate.label.split(",").slice(1,4).join(",")}</small></p><em>{candidate.distanceKm<1?`${Math.round(candidate.distanceKm*1000)} m`:`${candidate.distanceKm.toLocaleString("es-CO",{maximumFractionDigits:1})} km`}</em></button>)}</div>}
        <div className="work-zone-choice"><div><b>Zona del servicio</b><small>Define el valor mínimo por kilómetro</small></div><section><button type="button" className={serviceZone==="urban"?"active urban":"urban"} onClick={()=>{setServiceZone("urban");setPriceEdited(false)}}><span><CarFront size={19}/></span><p><b>Urbano</b><small>Dentro de la ciudad</small></p><em>{money.format(Number(urbanRate)||0)}/km</em></button><button type="button" className={serviceZone==="rural"?"active rural":"rural"} onClick={()=>{setServiceZone("rural");setPriceEdited(false)}}><span><Route size={19}/></span><p><b>Rural</b><small>Carretera o vereda</small></p><em>{money.format(Number(ruralRate)||0)}/km</em></button></section></div>
        <div className="work-trip-choice" aria-label="Tipo de recorrido"><button type="button" className={!roundTrip?"active":""} onClick={()=>{setRoundTrip(false);setPriceEdited(false)}}>Solo ida</button><button type="button" className={roundTrip?"active":""} onClick={()=>{setRoundTrip(true);setPriceEdited(false)}}>Ida y regreso</button></div>
        <button type="button" className="work-calculate" onClick={calculateRoute} disabled={routeStatus==="locating"||routeStatus==="calculating"}><Navigation size={19}/>{routeStatus==="calculating"?"Calculando ruta…":"Confirmar destino y calcular"}<ChevronRight size={18}/></button>
        <button type="button" className="work-manual-toggle" onClick={()=>setManualDistance(value=>!value)}>{manualDistance?"Ocultar ingreso manual":"¿No funciona el GPS? Ingresa los kilómetros"}</button>
        {manualDistance&&<label className="work-manual-distance"><span>Distancia de solo ida</span><div><input type="number" min="0" step="0.1" inputMode="decimal" value={manualKm} onChange={event=>applyManualKm(event.target.value)} placeholder="Ej. 18.5"/><b>km</b></div></label>}
        <div className={`work-route-status ${routeStatus}`} aria-live="polite">{routeStatus==="error"?<AlertTriangle size={17}/>:routeStatus==="ready"?<Check size={17}/>:<MapPin size={17}/>}<span>{routeMessage}</span></div>
        {serviceKm>0&&<div className="work-route-summary"><span><Route size={20}/><small>RECORRIDO</small><b>{serviceKm.toLocaleString("es-CO",{maximumFractionDigits:1})} km</b></span><span><TimerReset size={20}/><small>TIEMPO EN VÍA</small><b>{oneWayMinutes?`${Math.round(oneWayMinutes*(roundTrip?2:1))} min`:"Manual"}</b></span><span><Navigation size={20}/><small>TRAYECTO</small><b>{roundTrip?"Ida y regreso":"Solo ida"}</b></span></div>}
        <small className="work-map-credit">Ruta por carretera estimada con <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap</a> y OSRM. Puede variar por tráfico, cierres o desvíos.</small>
      </article>

      <article className="work-price-card">
        <div className="work-price-top"><span><Gauge size={22}/></span><div><small>PASO 2 · TU PRECIO</small><h3>{serviceKm?"Costo calculado":"Primero calcula la ruta"}</h3></div></div>
        <div className="work-price-editor"><label><span>Precio para el cliente</span><div><b>$</b><input type="number" min="0" step="1000" inputMode="numeric" value={displayedPrice} onChange={event=>{setFinalPrice(event.target.value);setPriceEdited(true);setSaved(false)}}/></div></label>{priceEdited&&<button type="button" onClick={resetSuggestedPrice}>Usar sugerido {money.format(recommendedPrice)}</button>}</div>
        <div className={`work-rate-floor ${minimumRateApplied?"applied":"covered"}`}><span><Route size={18}/></span><p><b>{minimumRateApplied?"Tarifa mínima aplicada":"Tus costos superan la tarifa mínima"}</b><small>{serviceZone==="urban"?"Urbano":"Rural"} · {money.format(minimumRate)} por km{Number(commission)?" · comisión incluida":""}</small></p><strong>{money.format(commercialPrice)}</strong></div>
        <div className="work-price-kpis"><span><small>COSTO REAL</small><b>{money.format(operatingCost)}</b></span><span><small>GANANCIA EST.</small><b className={expectedProfit<0?"negative":""}>{money.format(expectedProfit)}</b></span><span><small>PRECIO / KM</small><b>{money.format(pricePerKm)}</b></span></div>
        <div className="work-cost-parts">
          <div className="fuel"><span><Fuel size={19}/></span><p><small>COMBUSTIBLE</small><b>{money.format(fuelCost)}</b></p></div>
          <div className="wear"><span><Disc3 size={19}/></span><p><small>DESGASTE</small><b>{money.format(wearCost)}</b></p></div>
          <div className="time"><span><TimerReset size={19}/></span><p><small>TU TIEMPO</small><b>{money.format(timeCost)}</b></p></div>
          <div className="extras"><span><ReceiptText size={19}/></span><p><small>PEAJES + OTROS</small><b>{money.format(extrasCost)}</b></p></div>
          <div className="commission"><span><CircleDollarSign size={19}/></span><p><small>COMISIÓN</small><b>{money.format(commissionAmount)}</b></p></div>
        </div>
        {!recentFuel&&<div className="work-cost-warning"><AlertTriangle size={17}/><span>Registra el precio del galón que pagaste hoy para calcular combustible.</span></div>}
        {!validPercent&&<div className="form-error"><AlertTriangle size={16}/>Comisión y utilidad juntas deben ser menores al 95%.</div>}
        {error&&<div className="form-error"><AlertTriangle size={16}/>{error}</div>}
        {shareMessage&&<div className="work-share-message"><Check size={16}/>{shareMessage}</div>}
        <div className="work-quote-actions"><button type="button" className="send" onClick={shareQuote} disabled={!selectedPrice||!serviceKm}><Send size={18}/>Enviar cotización</button><button type="button" className="save" disabled={saving||!selectedPrice||serviceKm<=0||!validPercent} onClick={async()=>{setSaving(true);setSaved(false);setError("");try{await saveQuote(record);setSaved(true)}catch(saveError){setError(saveError instanceof Error?saveError.message:"No pudimos guardar la cotización")}finally{setSaving(false)}}}><Save size={18}/>{saving?"Guardando…":saved?"Guardada":"Guardar"}</button></div>
      </article>
    </div>

    <details className="work-cost-settings">
      <summary><span><Settings size={19}/><b>Ajustar gasolina, desgaste y comisión</b></span><ChevronRight size={18}/></summary>
      <div className="work-settings-grid">
        <Field label="Tarifa urbana por km"><div className="input-unit"><span>$</span><input type="number" min="0" inputMode="numeric" value={urbanRate} onChange={event=>{setUrbanRate(event.target.value);setPriceEdited(false)}}/></div></Field>
        <Field label="Tarifa rural por km"><div className="input-unit"><span>$</span><input type="number" min="0" inputMode="numeric" value={ruralRate} onChange={event=>{setRuralRate(event.target.value);setPriceEdited(false)}}/></div></Field>
        <Field label="Precio del galón"><div className="input-unit"><span>$</span><input type="number" min="0" inputMode="numeric" value={fuelPrice} onChange={event=>{setFuelPrice(event.target.value);setPriceEdited(false)}}/></div></Field>
        <Field label="Rendimiento"><div className="input-unit"><input type="number" min="1" step="0.1" inputMode="decimal" value={efficiency} onChange={event=>{setEfficiency(event.target.value);setPriceEdited(false)}}/><span>km/gal</span></div></Field>
        <Field label="Desgaste por km"><div className="input-unit"><span>$</span><input type="number" min="0" inputMode="numeric" value={wearPerKm} onChange={event=>{setWearPerKm(event.target.value);setPriceEdited(false)}}/></div></Field>
        <Field label="Peajes del recorrido"><div className="input-unit"><span>$</span><input type="number" min="0" inputMode="numeric" value={tolls} onChange={event=>{setTolls(event.target.value);setPriceEdited(false)}}/></div></Field>
        <Field label="Otros gastos"><div className="input-unit"><span>$</span><input type="number" min="0" inputMode="numeric" value={otherCosts} onChange={event=>{setOtherCosts(event.target.value);setPriceEdited(false)}}/></div></Field>
        <Field label="Valor de tu hora"><div className="input-unit"><span>$</span><input type="number" min="0" inputMode="numeric" value={hourlyRate} onChange={event=>{setHourlyRate(event.target.value);setPriceEdited(false)}}/></div></Field>
        <Field label="Comisión del servicio"><div className="input-unit"><input type="number" min="0" max="80" inputMode="decimal" value={commission} onChange={event=>{setCommission(event.target.value);setPriceEdited(false)}}/><span>%</span></div></Field>
        <Field label="Utilidad que deseas"><div className="input-unit"><input type="number" min="0" max="80" inputMode="decimal" value={margin} onChange={event=>{setMargin(event.target.value);setPriceEdited(false)}}/><span>%</span></div></Field>
      </div>
      <div className="work-settings-note"><Sparkles size={17}/><p><b>{recentFuel?`Gasolina tomada de tu último tanqueo: ${money.format(recentFuel.pricePerGallon)}/galón.`:"El precio del combustible queda pendiente."}</b><span>{measuredWear?`Desgaste calculado con tu historial: ${money.format(measuredWear)}/km.`:"Usamos un valor inicial editable de $300/km hasta tener historial."}</span></p></div>
    </details>

    {quotes.length>0&&<article className="card quote-history"><Title over="COTIZACIONES GUARDADAS" title="Precios calculados recientemente"/>{quotes.slice(0,4).map(quote=><Movement key={quote.id||quote.createdAt} icon={CircleDollarSign} title={quote.serviceName} meta={`${quote.serviceKm.toLocaleString("es-CO",{maximumFractionDigits:1})} km de servicio · costo ${money.format(quote.operatingCost)}`} amount={money.format(quote.recommendedPrice)} time={new Date(quote.createdAt).toLocaleDateString("es-CO",{day:"numeric",month:"short"})} good/>)}</article>}
  </section>
}

function PricingCalculator({sessions,fuelRecords,maintenanceRecords,trips,vehicle,quotes,saveQuote}:{sessions:WorkSessionRecord[];fuelRecords:FuelRecord[];maintenanceRecords:MaintenanceRecord[];trips:TripRecord[];vehicle:VehicleProfile|null;quotes:ServiceQuoteRecord[];saveQuote:(record:ServiceQuoteRecord)=>Promise<void>}) {
  const sortedFuel=[...fuelRecords].sort((a,b)=>a.odometer-b.odometer);
  const measuredEfficiencies=sortedFuel.slice(1).map((record,index)=>(record.odometer-sortedFuel[index].odometer)/record.gallons).filter(value=>value>=5&&value<=150);
  const measuredEfficiency=measuredEfficiencies.length?measuredEfficiencies.reduce((sum,value)=>sum+value,0)/measuredEfficiencies.length:0;
  const historicalKm=sessions.filter(session=>session.endedAt&&session.endOdometer!==null).reduce((sum,session)=>sum+Math.max(0,(session.endOdometer||0)-session.startOdometer),0);
  const measuredWear=historicalKm?Math.round(maintenanceRecords.reduce((sum,record)=>sum+record.total,0)/historicalKm):0;
  const initialOdometer=Number(vehicle?.odometer||sessions[0]?.endOdometer||sessions[0]?.startOdometer||0);
  const [serviceName,setServiceName]=useState("Servicio particular");
  const [startOdometer,setStartOdometer]=useState(String(initialOdometer));const [endOdometer,setEndOdometer]=useState(String(initialOdometer));
  const [extraKm,setExtraKm]=useState("0");const [fuelPrice,setFuelPrice]=useState(String(fuelRecords[0]?.pricePerGallon||0));
  const [efficiency,setEfficiency]=useState(String(measuredEfficiency?Math.round(measuredEfficiency*10)/10:35));const [wearPerKm,setWearPerKm]=useState(String(measuredWear));
  const [tolls,setTolls]=useState("0");const [otherCosts,setOtherCosts]=useState("0");const [hours,setHours]=useState("1");const [hourlyRate,setHourlyRate]=useState("0");
  const [commission,setCommission]=useState("0");const [margin,setMargin]=useState("25");const [saving,setSaving]=useState(false);const [saved,setSaved]=useState(false);const [error,setError]=useState("");
  const serviceKm=Math.max(0,(Number(endOdometer)||0)-(Number(startOdometer)||0)),totalKm=serviceKm+(Number(extraKm)||0),efficiencyValue=Math.max(.1,Number(efficiency)||0);
  const fuelCost=Math.round(totalKm/efficiencyValue*(Number(fuelPrice)||0)),wearCost=Math.round(totalKm*(Number(wearPerKm)||0)),timeCost=Math.round((Number(hours)||0)*(Number(hourlyRate)||0));
  const operatingCost=fuelCost+wearCost+(Number(tolls)||0)+(Number(otherCosts)||0)+timeCost,combinedPct=(Number(commission)||0)+(Number(margin)||0),validPercent=combinedPct<95;
  const recommendedPrice=validPercent&&serviceKm>0?Math.ceil((operatingCost/Math.max(.05,1-combinedPct/100))/1000)*1000:0,pricePerKm=serviceKm?Math.round(recommendedPrice/serviceKm):0;
  const record:ServiceQuoteRecord={serviceName:serviceName.trim()||"Servicio particular",createdAt:new Date().toISOString(),startOdometer:Number(startOdometer)||0,endOdometer:Number(endOdometer)||0,serviceKm,extraKm:Number(extraKm)||0,totalKm,fuelPrice:Number(fuelPrice)||0,efficiencyKpg:efficiencyValue,fuelCost,wearPerKm:Number(wearPerKm)||0,wearCost,tolls:Number(tolls)||0,otherCosts:Number(otherCosts)||0,hours:Number(hours)||0,hourlyRate:Number(hourlyRate)||0,timeCost,commissionPct:Number(commission)||0,marginPct:Number(margin)||0,operatingCost,recommendedPrice,pricePerKm};
  const useLastTrip=()=>{if(!trips[0])return;setEndOdometer(String((Number(startOdometer)||0)+trips[0].distanceKm));setHours(String(Math.max(.1,Math.round(trips[0].durationSeconds/360)/10)))};
  return <section className="quote-module"><div className="quote-heading"><div><small>COTIZADOR POR KILÓMETRO</small><h2>Calcula antes de decir cuánto cobras</h2><p>Combustible, desgaste, tiempo, peajes y utilidad en una sola cuenta.</p></div>{trips[0]&&<button onClick={useLastTrip}><Navigation size={16}/>Usar último GPS · {trips[0].distanceKm.toLocaleString("es-CO",{maximumFractionDigits:1})} km</button>}</div>
    <div className="quote-layout"><article className="card quote-form"><div className="quote-fields"><Field label="Nombre del servicio" wide><input value={serviceName} onChange={e=>setServiceName(e.target.value)} placeholder="Ej. Aeropuerto El Dorado"/></Field><Field label="Odómetro inicial"><div className="input-unit"><input type="number" min="0" step="0.1" value={startOdometer} onChange={e=>setStartOdometer(e.target.value)}/><span>km</span></div></Field><Field label="Odómetro final"><div className="input-unit"><input type="number" min="0" step="0.1" value={endOdometer} onChange={e=>setEndOdometer(e.target.value)}/><span>km</span></div></Field><Field label="Recogida o retorno"><div className="input-unit"><input type="number" min="0" step="0.1" value={extraKm} onChange={e=>setExtraKm(e.target.value)}/><span>km</span></div></Field><Field label="Precio del galón"><div className="input-unit"><span>$</span><input type="number" min="0" value={fuelPrice} onChange={e=>setFuelPrice(e.target.value)}/></div></Field><Field label="Rendimiento"><div className="input-unit"><input type="number" min="1" step="0.1" value={efficiency} onChange={e=>setEfficiency(e.target.value)}/><span>km/gal</span></div></Field><Field label="Desgaste por km"><div className="input-unit"><span>$</span><input type="number" min="0" value={wearPerKm} onChange={e=>setWearPerKm(e.target.value)}/></div></Field><Field label="Peajes (total)"><div className="input-unit"><span>$</span><input type="number" min="0" value={tolls} onChange={e=>setTolls(e.target.value)}/></div></Field><Field label="Otros gastos"><div className="input-unit"><span>$</span><input type="number" min="0" value={otherCosts} onChange={e=>setOtherCosts(e.target.value)}/></div></Field><Field label="Duración estimada"><div className="input-unit"><input type="number" min="0" step="0.25" value={hours} onChange={e=>setHours(e.target.value)}/><span>horas</span></div></Field><Field label="Valor de tu hora"><div className="input-unit"><span>$</span><input type="number" min="0" value={hourlyRate} onChange={e=>setHourlyRate(e.target.value)}/></div></Field><Field label="Comisión de plataforma"><div className="input-unit"><input type="number" min="0" max="80" value={commission} onChange={e=>setCommission(e.target.value)}/><span>%</span></div></Field><Field label="Utilidad deseada"><div className="input-unit"><input type="number" min="0" max="80" value={margin} onChange={e=>setMargin(e.target.value)}/><span>%</span></div></Field></div><div className="quote-source"><Sparkles size={17}/><span><b>{measuredEfficiency?"Rendimiento calculado con tus tanqueos":"Rendimiento inicial editable"}</b><small>{measuredWear?`Desgaste sugerido con tu historial: ${money.format(measuredWear)}/km`:"Configura el desgaste por kilómetro para incluir mantenimiento y depreciación."}</small></span></div></article>
      <article className="quote-result"><small>PRECIO RECOMENDADO</small><b>{money.format(recommendedPrice)}</b><p>Redondeado al siguiente múltiplo de $1.000</p><div className="quote-kpis"><span><small>COSTO REAL</small><b>{money.format(operatingCost)}</b></span><span><small>POR KM COBRADO</small><b>{money.format(pricePerKm)}</b></span><span><small>KM TOTALES</small><b>{totalKm.toLocaleString("es-CO",{maximumFractionDigits:1})}</b></span></div><div className="quote-breakdown"><Cost name="Combustible" value={money.format(fuelCost)} color="#c9ff38"/><Cost name="Desgaste del vehículo" value={money.format(wearCost)} color="#30dfb2"/><Cost name="Tu tiempo" value={money.format(timeCost)} color="#8d7dff"/><Cost name="Peajes y otros" value={money.format((Number(tolls)||0)+(Number(otherCosts)||0))} color="#ffad67"/></div>{!validPercent&&<div className="form-error"><AlertTriangle size={16}/>Comisión y utilidad juntas deben ser menores al 95%.</div>}{error&&<div className="form-error"><AlertTriangle size={16}/>{error}</div>}<button className="save-quote" disabled={saving||serviceKm<=0||!validPercent} onClick={async()=>{setSaving(true);setSaved(false);setError("");try{await saveQuote(record);setSaved(true)}catch(err){setError(err instanceof Error?err.message:"No pudimos guardar la cotización")}finally{setSaving(false)}}}><Save size={17}/>{saving?"Guardando…":saved?"Cotización guardada":"Guardar cotización"}</button><small className="quote-note">El precio es una recomendación basada en los valores ingresados. Los peajes se agregan manualmente.</small></article></div>
    {quotes.length>0&&<article className="card quote-history"><Title over="COTIZACIONES GUARDADAS" title="Precios calculados recientemente"/>{quotes.slice(0,4).map(quote=><Movement key={quote.id||quote.createdAt} icon={CircleDollarSign} title={quote.serviceName} meta={`${quote.serviceKm.toLocaleString("es-CO",{maximumFractionDigits:1})} km de servicio · costo ${money.format(quote.operatingCost)}`} amount={money.format(quote.recommendedPrice)} time={new Date(quote.createdAt).toLocaleDateString("es-CO",{day:"numeric",month:"short"})} good/>)}</article>}
  </section>
}

function WorkPage({sessions,fuelRecords,maintenanceRecords,trips,vehicle,quotes,saveQuote}:{sessions:WorkSessionRecord[];fuelRecords:FuelRecord[];maintenanceRecords:MaintenanceRecord[];trips:TripRecord[];vehicle:VehicleProfile|null;quotes:ServiceQuoteRecord[];saveQuote:(record:ServiceQuoteRecord)=>Promise<void>}) {
  const [week,setWeek]=useState(false),[now]=useState(()=>Date.now()),since=now-(week?7:31)*86400000,within=(date:string)=>new Date(date).getTime()>=since,filtered=sessions.filter(session=>session.endedAt&&within(session.startedAt)),income=filtered.reduce((sum,session)=>sum+session.income,0),otherExpenses=filtered.reduce((sum,session)=>sum+session.expenses,0),fuel=fuelRecords.filter(record=>within(record.occurredAt)).reduce((sum,record)=>sum+record.total,0),maintenance=maintenanceRecords.filter(record=>within(record.occurredAt)).reduce((sum,record)=>sum+record.total,0),expenses=otherExpenses+fuel+maintenance,net=income-expenses,margin=income?Math.round(net/income*100):0;
  return <div className="page inner work-v19"><section className="work-command-head"><div><small>MI TRABAJO · COTIZADOR</small><h1>¿Cuánto debes cobrar?</h1><p>Elige el destino. Autoram calcula la ruta, tus costos y un precio rentable para enviar al cliente.</p></div><div className="rate-board"><span><MapPin size={18}/><small>URBANO</small><b>$1.500 <em>/ km</em></b></span><span><Route size={18}/><small>RURAL</small><b>$2.000 <em>/ km</em></b></span><span><ReceiptText size={18}/><small>ADICIONALES</small><b>Peajes <em>aparte</em></b></span></div></section><RoutePricingCalculator sessions={sessions} fuelRecords={fuelRecords} maintenanceRecords={maintenanceRecords} trips={trips} vehicle={vehicle} quotes={quotes} saveQuote={saveQuote}/><div className="period"><button className={week?"active":""} onClick={()=>setWeek(true)}>Últimos 7 días</button><button className={!week?"active":""} onClick={()=>setWeek(false)}>Últimos 31 días</button></div><section className="money-grid"><Money label="Ingresos brutos" value={income} icon={ArrowUpRight} tone="green"/><Money label="Gastos totales" value={expenses} icon={ArrowDownRight} tone="orange"/><Money label="Ganancia neta" value={net} icon={Sparkles} tone="lime"/></section><section className="two-col work"><article className="card"><Title over="DISTRIBUCIÓN DE GASTOS" title="¿A dónde se fue el dinero?"/><div className="donut-row"><div className="donut"><span><b>{income?Math.round(expenses/income*100):0}%</b><small>de ingresos</small></span></div><div className="costs"><Cost name="Combustible" value={money.format(fuel)} color="#c9ff38"/><Cost name="Mantenimiento" value={money.format(maintenance)} color="#30dfb2"/><Cost name="Otros de jornada" value={money.format(otherExpenses)} color="#626a6d"/></div></div></article><article className="card goal"><Title over="RESULTADO REAL" title={filtered.length?"Balance del periodo":"Completa tu primera jornada"}/><b>{margin}% <small>de margen neto</small></b><i><em style={{width:`${Math.max(0,Math.min(100,margin))}%`}}/></i><p>{filtered.length?<>Registraste <strong>{filtered.length} jornada{filtered.length===1?"":"s"}</strong> y una ganancia neta de <strong>{money.format(net)}</strong>.</>:"Al cerrar una jornada con ingresos y gastos, Autoram calculará aquí tu rentabilidad."}</p></article></section>{filtered.length>0&&<article className="card maintenance-history"><Title over="JORNADAS CERRADAS" title="Historial de trabajo"/>{filtered.slice(0,6).map(session=><Movement key={session.id} icon={BriefcaseBusiness} title={session.role==="plataforma"?(JSON.parse(session.platforms||"[]").join(" + ")||"Plataforma"):session.activity||"Independiente"} meta={`${session.startOdometer.toLocaleString("es-CO")} → ${session.endOdometer?.toLocaleString("es-CO")} km`} amount={money.format(session.income-session.expenses)} time={new Date(session.startedAt).toLocaleDateString("es-CO",{day:"numeric",month:"short"})}/>)}</article>}</div>
}
function Money({label,value,icon:Icon,tone}:{label:string,value:number,icon:typeof ArrowUpRight,tone:string}) { return <article className={`money ${tone}`}><span><Icon size={21}/></span><small>{label}</small><b>{money.format(value)}</b><p>{tone==="orange"?"Jornadas, combustible y servicios":tone==="lime"?"Ingresos menos gastos":"Ingresos de jornadas cerradas"}</p></article> }
function Cost({name,value,color}:{name:string,value:string,color:string}) { return <div><span><i style={{background:color}}/>{name}</span><b>{value}</b></div> }

function WorkSetup({vehicle,city,close,start}:{vehicle:VehicleProfile|null;city:string;close:()=>void;start:(v:WorkConfig)=>Promise<void>}) {
  const [role,setRole]=useState<"independiente"|"plataforma">("plataforma"); const [platforms,setPlatforms]=useState<string[]>(["Uber"]); const [activity,setActivity]=useState("Transporte particular");
  const [saving,setSaving]=useState(false);const [error,setError]=useState("");
  const toggle=(name:string)=>setPlatforms(v=>v.includes(name)?v.filter(p=>p!==name):[...v,name]);
  return <div className="backdrop" onMouseDown={close}><section className="work-setup" onMouseDown={e=>e.stopPropagation()} role="dialog" aria-modal="true"><div className="quick-head"><div><small>ANTES DE EMPEZAR</small><h2>Configura tu jornada</h2><p>Así podremos separar correctamente tus ingresos y gastos.</p></div><button className="icon" onClick={close}><X size={20}/></button></div>{error&&<div className="form-error"><AlertTriangle size={16}/>{error}</div>}<div className="role-choice"><button className={role==="independiente"?"selected":""} onClick={()=>setRole("independiente")}><span><UserRound size={22}/></span><div><b>Independiente</b><small>Servicios propios o clientes directos</small></div><i>{role==="independiente"&&<Check size={15}/>}</i></button><button className={role==="plataforma"?"selected":""} onClick={()=>setRole("plataforma")}><span><Navigation size={22}/></span><div><b>Plataforma</b><small>Trabajas conectado a una o varias apps</small></div><i>{role==="plataforma"&&<Check size={15}/>}</i></button></div>{role==="plataforma"?<div className="setup-block"><label>Selecciona las plataformas</label><div className="platform-choice">{["Uber","DiDi","inDrive","Cabify","Picap","Rappi"].map(p=><button key={p} className={platforms.includes(p)?"selected":""} onClick={()=>toggle(p)}>{platforms.includes(p)&&<Check size={13}/>} {p}</button>)}</div><small>Puedes seleccionar varias aplicaciones.</small></div>:<div className="setup-block"><label>Tipo de actividad independiente</label><select value={activity} onChange={e=>setActivity(e.target.value)}><option>Transporte particular</option><option>Taxi</option><option>Traslado empresarial</option><option>Mensajería o domicilios</option><option>Turismo y recorridos</option><option>Otro servicio</option></select></div>}<div className="setup-details"><Field label="Kilometraje inicial" required><div className="input-unit"><input type="number" id="work-odometer" defaultValue={vehicle?.odometer||"0"}/><span>km</span></div></Field><Field label="Vehículo"><select disabled><option>{vehicle?.brand} {vehicle?.model} · {vehicle?.plate}</option></select></Field></div><div className="setup-note"><MapPin size={17}/><span><b>Ubicación inicial</b><small>{city} · GPS del dispositivo</small></span><Check size={16}/></div><div className="form-actions"><button type="button" onClick={close} disabled={saving}>Cancelar</button><button className="primary" disabled={saving||(role==="plataforma"&&platforms.length===0)} onClick={async()=>{const el=document.getElementById("work-odometer") as HTMLInputElement|null;setSaving(true);setError("");try{await start({role,platforms,activity,odometer:el?.value||vehicle?.odometer||"0"})}catch(err){setError(err instanceof Error?err.message:"No pudimos iniciar la jornada");setSaving(false)}}}><Play size={17} fill="currentColor"/>{saving?"Iniciando…":"Comenzar jornada"}</button></div></section></div>
}

function WorkFinish({startOdometer,close,finish}:{startOdometer:number;close:()=>void;finish:(data:{endOdometer:number;income:number;expenses:number})=>Promise<void>}){
  const [endOdometer,setEndOdometer]=useState(String(startOdometer));const [income,setIncome]=useState("");const [expenses,setExpenses]=useState("");const [saving,setSaving]=useState(false);const [error,setError]=useState("");
  const distance=Math.max(0,Number(endOdometer)-startOdometer),net=(Number(income)||0)-(Number(expenses)||0);
  return <div className="backdrop" onMouseDown={close}><section className="work-setup finish-work" onMouseDown={e=>e.stopPropagation()} role="dialog" aria-modal="true"><div className="quick-head"><div><small>CIERRE DE JORNADA</small><h2>¿Cómo terminó el día?</h2><p>Confirma kilómetros, ingresos y gastos para calcular la ganancia real.</p></div><button className="icon" onClick={close}><X size={20}/></button></div>{error&&<div className="form-error"><AlertTriangle size={16}/>{error}</div>}<div className="setup-details"><Field label="Kilometraje final" required><div className="input-unit"><input type="number" min={startOdometer} value={endOdometer} onChange={e=>setEndOdometer(e.target.value)}/><span>km</span></div></Field><Field label="Ingresos de la jornada" required><div className="input-unit"><span>$</span><input type="number" min="0" value={income} onChange={e=>setIncome(e.target.value)} placeholder="0"/></div></Field><Field label="Gastos adicionales"><div className="input-unit"><span>$</span><input type="number" min="0" value={expenses} onChange={e=>setExpenses(e.target.value)} placeholder="0"/></div></Field><Field label="Distancia calculada"><div className="input-unit"><input value={distance.toFixed(1)} disabled/><span>km</span></div></Field></div><div className="finish-balance"><span><small>GANANCIA DE LA JORNADA</small><b className={net<0?"negative":""}>{money.format(net)}</b></span><span><small>RECORRIDO</small><b>{distance.toLocaleString("es-CO")} km</b></span></div><div className="form-actions"><button type="button" onClick={close} disabled={saving}>Seguir trabajando</button><button className="primary" disabled={saving||!income||Number(endOdometer)<startOdometer} onClick={async()=>{setSaving(true);setError("");try{await finish({endOdometer:Number(endOdometer),income:Number(income)||0,expenses:Number(expenses)||0})}catch(err){setError(err instanceof Error?err.message:"No pudimos cerrar la jornada");setSaving(false)}}}><Check size={17}/>{saving?"Guardando…":"Cerrar jornada"}</button></div></section></div>
}

function FormShell({title,step,close,children}:{title:string;step:string;close:()=>void;children:React.ReactNode}) { return <div className="form-backdrop" onMouseDown={close}><section className="form-sheet" onMouseDown={e=>e.stopPropagation()} aria-modal="true" role="dialog"><div className="form-head"><div><small>{step}</small><h2>{title}</h2></div><button className="icon" onClick={close} aria-label="Cerrar formulario"><X size={20}/></button></div>{children}</section></div> }

function Field({label,required,children,wide}:{label:string;required?:boolean;children:React.ReactNode;wide?:boolean}) { return <label className={`field ${wide?"wide":""}`}><span>{label}{required&&<b>*</b>}</span>{children}</label> }

function FuelForm({vehicle,close,save}:{vehicle:VehicleProfile|null;close:()=>void;save:(v:FuelRecord)=>Promise<void>}) {
  const [gallons,setGallons]=useState(""); const [price,setPrice]=useState(""); const [saving,setSaving]=useState(false);const [error,setError]=useState("");const calculated=Math.round((Number(gallons)||0)*(Number(price)||0));
  return <FormShell title="Registrar tanqueo" step="COMBUSTIBLE · NUEVO REGISTRO" close={close}><form onSubmit={async e=>{e.preventDefault();if(saving)return;const d=new FormData(e.currentTarget);const record:FuelRecord={occurredAt:String(d.get("date")||new Date().toISOString()),odometer:Number(d.get("odometer")||0),station:String(d.get("station")||"Estación"),fuelType:String(d.get("fuel")||"Gasolina corriente"),gallons:Number(gallons),pricePerGallon:Number(price),total:calculated,payment:String(d.get("payment")||""),fillType:String(d.get("fill")||""),notes:String(d.get("notes")||"")};setSaving(true);setError("");try{await save(record)}catch(err){setError(err instanceof Error?err.message:"No pudimos guardar el tanqueo");setSaving(false)}}}>{error&&<div className="form-error"><AlertTriangle size={16}/>{error}</div>}<div className="form-intro"><span><Fuel size={23}/></span><div><b>{vehicle?.brand} {vehicle?.model} · {vehicle?.plate}</b><small>El rendimiento se calculará al guardar este tanqueo.</small></div></div><div className="form-grid">
    <Field label="Fecha y hora" required><input name="date" type="datetime-local" defaultValue={localDateTimeInput()} required/></Field>
    <Field label="Kilometraje actual" required><div className="input-unit"><input name="odometer" type="number" defaultValue={vehicle?.odometer||"0"} min="0" required/><span>km</span></div></Field>
    <Field label="Estación de servicio" required><input name="station" placeholder="Nombre de la estación" required/></Field>
    <Field label="Tipo de combustible"><select name="fuel"><option>Gasolina corriente</option><option>Gasolina extra</option><option>ACPM / Diésel</option><option>Gas natural</option></select></Field>
    <Field label="Cantidad cargada" required><div className="input-unit"><input name="gallons" type="number" step="0.01" value={gallons} onChange={e=>setGallons(e.target.value)} required/><span>gal</span></div></Field>
    <Field label="Precio por galón" required><div className="input-unit"><span>$</span><input name="price" type="number" value={price} onChange={e=>setPrice(e.target.value)} required/></div></Field>
    <Field label="Método de pago"><select name="payment"><option>Tarjeta débito</option><option>Efectivo</option><option>Tarjeta crédito</option><option>Transferencia</option></select></Field>
    <Field label="Tipo de carga"><select name="fill"><option>Tanque lleno</option><option>Carga parcial</option></select></Field>
    <Field label="Observaciones" wide><textarea name="notes" placeholder="Ejemplo: viaje por carretera, uso de aire acondicionado..."/></Field>
  </div><div className="production-note"><ShieldCheck size={17}/><span><b>Registro protegido</b><small>Los datos se guardan en tu cuenta. La carga de facturas se habilitará después de validar esta beta.</small></span></div><div className="calculation"><div><ReceiptText size={20}/><span><small>TOTAL CALCULADO</small><b>{money.format(calculated)}</b></span></div><span><small>Validación</small><b>{calculated>0?"Lista":"Revisa los valores"}</b></span></div><div className="form-actions"><button type="button" onClick={close} disabled={saving}>Cancelar</button><button className="primary" type="submit" disabled={saving||calculated<=0}><Save size={17}/>{saving?"Guardando…":"Guardar tanqueo"}</button></div></form></FormShell>
}

function MaintenanceForm({vehicle,close,save}:{vehicle:VehicleProfile|null;close:()=>void;save:(v:MaintenanceRecord)=>Promise<void>}) {
  const [labor,setLabor]=useState(""); const [parts,setParts]=useState(""); const [saving,setSaving]=useState(false);const [error,setError]=useState("");const total=(Number(labor)||0)+(Number(parts)||0);
  return <FormShell title="Registrar mantenimiento" step="SALUD MECÁNICA · NUEVO REGISTRO" close={close}><form onSubmit={async e=>{e.preventDefault();if(saving)return;const d=new FormData(e.currentTarget);const record:MaintenanceRecord={occurredAt:String(d.get("date")||new Date().toISOString()),odometer:Number(d.get("odometer")||0),movementType:String(d.get("type")||"Servicio preventivo"),category:String(d.get("category")||"Motor y fluidos"),issue:String(d.get("issue")||""),workDone:String(d.get("work")||""),shop:String(d.get("shop")||""),phone:String(d.get("phone")||""),laborCost:Number(labor)||0,partsCost:Number(parts)||0,total,warranty:String(d.get("warranty")||""),nextKm:d.get("nextKm")?Number(d.get("nextKm")):null,notes:String(d.get("notes")||"")};setSaving(true);setError("");try{await save(record)}catch(err){setError(err instanceof Error?err.message:"No pudimos guardar el mantenimiento");setSaving(false)}}}>{error&&<div className="form-error"><AlertTriangle size={16}/>{error}</div>}<div className="form-intro"><span><Wrench size={23}/></span><div><b>{vehicle?.brand} {vehicle?.model} · {vehicle?.plate}</b><small>Guarda costos, taller, garantía y el próximo servicio.</small></div></div><div className="form-grid">
    <Field label="Tipo de movimiento" required><select name="type"><option>Servicio preventivo</option><option>Reparación</option><option>Compra de repuesto</option><option>Emergencia</option></select></Field>
    <Field label="Categoría" required><select name="category"><option>Motor y fluidos</option><option>Llantas y frenos</option><option>Sistema eléctrico</option><option>Suspensión y dirección</option><option>Carrocería</option><option>Climatización</option></select></Field>
    <Field label="Fecha" required><input name="date" type="date" defaultValue={localDateInput()} required/></Field>
    <Field label="Kilometraje" required><div className="input-unit"><input name="odometer" type="number" defaultValue={vehicle?.odometer||"0"} required/><span>km</span></div></Field>
    <Field label="Problema o motivo" wide required><input name="issue" placeholder="Describe la novedad encontrada" required/></Field>
    <Field label="Trabajo realizado" wide required><textarea name="work" placeholder="Describe exactamente lo realizado" required/></Field>
    <Field label="Taller o mecánico" required><input name="shop" placeholder="Nombre del taller" required/></Field>
    <Field label="Teléfono / WhatsApp"><input name="phone" type="tel" placeholder="300 000 0000"/></Field>
    <Field label="Mano de obra"><div className="input-unit"><span>$</span><input name="labor" type="number" value={labor} onChange={e=>setLabor(e.target.value)}/></div></Field>
    <Field label="Repuestos"><div className="input-unit"><span>$</span><input name="parts" type="number" value={parts} onChange={e=>setParts(e.target.value)}/></div></Field>
    <Field label="Garantía"><select name="warranty"><option>Sin garantía</option><option>30 días</option><option>3 meses</option><option>6 meses</option><option>1 año</option></select></Field>
    <Field label="Próximo servicio"><div className="input-unit"><input name="nextKm" type="number" defaultValue={String((Number(vehicle?.odometer)||0)+5000)}/><span>km</span></div></Field>
    <Field label="Observaciones" wide><textarea name="notes" placeholder="Recomendaciones del taller, referencias de repuestos..."/></Field>
  </div><div className="production-note"><ShieldCheck size={17}/><span><b>Historial permanente</b><small>Guardaremos taller, costos y garantía. Los documentos se activarán después de validar esta beta.</small></span></div><div className="calculation"><div><Wrench size={20}/><span><small>COSTO TOTAL</small><b>{money.format(total)}</b></span></div><span><small>Registro</small><b>Historial permanente</b></span></div><div className="form-actions"><button type="button" onClick={close} disabled={saving}>Cancelar</button><button className="primary" type="submit" disabled={saving}><Save size={17}/>{saving?"Guardando…":"Guardar servicio"}</button></div></form></FormShell>
}

function DocumentForm({vehicle,close,save}:{vehicle:VehicleProfile|null;close:()=>void;save:(v:VehicleDocumentRecord)=>Promise<void>}) {
  const [saving,setSaving]=useState(false);const [error,setError]=useState("");
  return <FormShell title="Registrar documento" step="VEHÍCULO · NUEVO DOCUMENTO" close={close}><form onSubmit={async event=>{event.preventDefault();if(saving)return;const data=new FormData(event.currentTarget);const record:VehicleDocumentRecord={documentType:String(data.get("documentType")||""),documentNumber:String(data.get("documentNumber")||""),issuedAt:String(data.get("issuedAt")||""),expiresAt:String(data.get("expiresAt")||""),provider:String(data.get("provider")||""),notes:String(data.get("notes")||"")};setSaving(true);setError("");try{await save(record)}catch(reason){setError(reason instanceof Error?reason.message:"No pudimos guardar el documento");setSaving(false)}}}>{error&&<div className="form-error"><AlertTriangle size={16}/>{error}</div>}<div className="form-intro"><span><FileCheck2 size={23}/></span><div><b>{vehicle?.brand} {vehicle?.model} · {vehicle?.plate}</b><small>La alerta se calculará únicamente con la fecha que registres.</small></div></div><div className="form-grid">
    <Field label="Tipo de documento" required><select name="documentType" required><option value="">Seleccionar</option><option>SOAT</option><option>Revisión tecnomecánica y gases</option><option>Seguro todo riesgo</option><option>Impuesto vehicular</option><option>Licencia de tránsito / Tarjeta de propiedad</option><option>Otro documento</option></select></Field>
    <Field label="Número o referencia"><input name="documentNumber" maxLength={80} placeholder="Póliza, certificado o referencia"/></Field>
    <Field label="Fecha de expedición"><input name="issuedAt" type="date"/></Field>
    <Field label="Fecha de vencimiento"><input name="expiresAt" type="date"/></Field>
    <Field label="Aseguradora o entidad" wide><input name="provider" maxLength={120} placeholder="Ej. Seguros Bolívar, CDA, Gobernación…"/></Field>
    <Field label="Observaciones" wide><textarea name="notes" maxLength={500} placeholder="Información adicional del documento"/></Field>
  </div><div className="production-note"><ShieldCheck size={17}/><span><b>Alerta basada en datos reales</b><small>Si el documento no vence, deja el campo de vencimiento vacío.</small></span></div><div className="form-actions"><button type="button" onClick={close} disabled={saving}>Cancelar</button><button className="primary" type="submit" disabled={saving}><Save size={17}/>{saving?"Guardando…":"Guardar documento"}</button></div></form></FormShell>
}

function Quick({close,go}:{close:()=>void,go:(v:View)=>void}) { const q=[{l:"Tanqueo",t:"Combustible y factura",i:Fuel,v:"tanqueos"},{l:"Recorrido",t:"Iniciar registro GPS",i:Navigation,v:"navegar"},{l:"Mantenimiento",t:"Servicio o reparación",i:Wrench,v:"mantenimiento"},{l:"Documento",t:"SOAT, tecnomecánica y vencimientos",i:FileCheck2,v:"documentos"},{l:"Diagnóstico",t:"Consultar código OBD2",i:Activity,v:"diagnostico"},{l:"Ingreso o gasto",t:"Movimiento de trabajo",i:WalletCards,v:"trabajo"}] as const; return <div className="backdrop" onMouseDown={close}><section className="quick" onMouseDown={e=>e.stopPropagation()}><div className="quick-head"><div><small>REGISTRO RÁPIDO</small><h2>¿Qué quieres agregar?</h2></div><button className="icon" onClick={close}><X size={20}/></button></div><div>{q.map(a=><button key={a.l} onClick={()=>{go(a.v);close()}}><span><a.i size={21}/></span><div><b>{a.l}</b><small>{a.t}</small></div><ChevronRight size={17}/></button>)}</div></section></div> }

function MoreMenu({active,close,go}:{active:View;close:()=>void;go:(v:View)=>void}) {
  const items=[
    {id:"tanqueos" as View,label:"Tanqueos",text:"Consumo y precio del combustible",icon:Fuel},
    {id:"mantenimiento" as View,label:"Mantenimiento",text:"Arreglos, talleres y costos",icon:Wrench},
    {id:"diagnostico" as View,label:"Diagnóstico",text:"Consulta de códigos OBD-II",icon:Activity},
    {id:"documentos" as View,label:"Documentos",text:"SOAT, tecnomecánica y vencimientos",icon:FileCheck2},
  ];
  return <div className="backdrop more-backdrop" onMouseDown={close}><section className="more-menu" onMouseDown={e=>e.stopPropagation()} role="dialog" aria-modal="true" aria-label="Más opciones"><div className="quick-head"><div><small>MÁS HERRAMIENTAS</small><h2>Todo tu vehículo</h2></div><button className="icon" onClick={close} aria-label="Cerrar"><X size={20}/></button></div><div className="more-grid">{items.map(item=><button key={item.id} className={active===item.id?"active":""} onClick={()=>go(item.id)}><span><item.icon size={22}/></span><div><b>{item.label}</b><small>{item.text}</small></div><ChevronRight size={18}/></button>)}</div></section></div>
}
